/**
 * Resolves the configured Backend API Origin from environment configuration
 * (`VITE_API_URL` or `NEXT_PUBLIC_API_URL`) without hard-coding a deployment host.
 */
export function getApiOrigin(overrideOrigin?: string): string {
  const procEnv = typeof process !== 'undefined' ? process.env : undefined;
  const metaEnv = typeof import.meta !== 'undefined' ? (import.meta as any).env : undefined;

  const raw =
    overrideOrigin !== undefined
      ? overrideOrigin
      : procEnv?.VITE_API_URL ||
        procEnv?.NEXT_PUBLIC_API_URL ||
        metaEnv?.VITE_API_URL ||
        metaEnv?.NEXT_PUBLIC_API_URL ||
        '';

  const trimmed = String(raw).trim().replace(/\/+$/, '');
  if (!trimmed) return '';
  if (!/^https?:\/\//i.test(trimmed) && !trimmed.startsWith('/')) {
    return `https://${trimmed}`;
  }
  return trimmed;
}

/**
 * Standard Shop Currency Configuration Interface
 * As specified in GET /api/shop/config
 */
export interface ShopConfig {
  currency: 'IRR' | 'IRT' | string;
  priceUnit?: string;
}

export const DEFAULT_SHOP_CONFIG: ShopConfig = {
  currency: 'IRR',
  priceUnit: 'rial',
};

/**
 * Converts a catalog display amount between IRR (Rial) and IRT (Toman) (1 IRT = 10 IRR).
 * Never converts to USD or arbitrary third currencies in the client.
 */
export function convertShopCurrencyAmount(
  amount: number,
  fromCurrency: string = DEFAULT_SHOP_CONFIG.currency,
  toCurrency: string = DEFAULT_SHOP_CONFIG.currency
): number {
  if (!Number.isFinite(amount)) return 0;
  const from = String(fromCurrency || DEFAULT_SHOP_CONFIG.currency).toUpperCase();
  const to = String(toCurrency || DEFAULT_SHOP_CONFIG.currency).toUpperCase();
  if (from === to) return amount;
  if (from === 'IRR' && to === 'IRT') return amount / 10;
  if (from === 'IRT' && to === 'IRR') return amount * 10;
  return amount;
}

/**
 * Formats a catalog or checkout amount using the target display currency.
 * The backend supports IRR and IRT directly without client-side USD conversions.
 */
export function formatShopCurrency(
  amount: number,
  currency: string = DEFAULT_SHOP_CONFIG.currency
): string {
  if (!Number.isFinite(amount)) return `0 ${currency}`;
  const normalized = Math.round(amount * 10) / 10;
  const formattedNumber = Number.isInteger(normalized)
    ? normalized.toLocaleString('en-US')
    : normalized.toLocaleString('en-US', {
        minimumFractionDigits: 0,
        maximumFractionDigits: 1,
      });

  if (currency === 'IRR') {
    return `${formattedNumber} IRR`;
  }
  if (currency === 'IRT') {
    return `${formattedNumber} IRT`;
  }
  return `${formattedNumber} ${currency}`;
}
