import { apiRequest } from './transport';
import {
  CustomerCart,
  CustomerOrder,
  RefundRecord,
  RefundEligibility,
  CustomerSubscription,
  ProductDownloadLink,
  StoreCreditBalance,
  StoreCreditTransaction,
  Pagination,
} from '../types';

export const meApi = {
  // ============================================
  // CART API (/api/shop/me/cart)
  // ============================================
  getCart: async (): Promise<CustomerCart> => {
    try {
      const data = await apiRequest<{ success: boolean; cart?: CustomerCart }>('/api/shop/me/cart', {
        method: 'GET',
      });
      return data.cart || { items: [] };
    } catch {
      return { items: [] };
    }
  },

  addItemToCart: async (
    itemType: string,
    itemId: string,
    variantId?: string | null,
    quantity = 1
  ): Promise<CustomerCart> => {
    const payload: Record<string, any> = {
      itemType,
      itemId,
      quantity: Math.max(1, Math.min(99, quantity)),
    };
    if (variantId) {
      payload.variantId = variantId;
    }
    const data = await apiRequest<{ success: boolean; cart: CustomerCart }>('/api/shop/me/cart/items', {
      method: 'POST',
      body: JSON.stringify(payload),
    });
    return data.cart || { items: [] };
  },

  removeItemFromCart: async (
    itemType: string,
    itemId: string,
    variantId?: string | null
  ): Promise<CustomerCart> => {
    let path = `/api/shop/me/cart/items/${encodeURIComponent(itemType)}/${encodeURIComponent(itemId)}`;
    if (variantId) {
      path += `?variantId=${encodeURIComponent(variantId)}`;
    }
    const data = await apiRequest<{ success: boolean; cart: CustomerCart }>(path, {
      method: 'DELETE',
    });
    return data.cart || { items: [] };
  },

  clearCart: async (): Promise<CustomerCart> => {
    const data = await apiRequest<{ success: boolean; cart: CustomerCart }>('/api/shop/me/cart', {
      method: 'DELETE',
    });
    return data.cart || { items: [] };
  },

  // ============================================
  // ORDERS API (/api/shop/me/orders)
  // ============================================
  getOrders: async (
    page = 1,
    limit = 25
  ): Promise<{ orders: CustomerOrder[]; pagination: Pagination }> => {
    const query = new URLSearchParams({
      page: String(Math.max(1, page)),
      limit: String(Math.min(100, Math.max(1, limit))),
    }).toString();

    const data = await apiRequest<{
      success: boolean;
      orders: CustomerOrder[];
      pagination: Pagination;
    }>(`/api/shop/me/orders?${query}`, {
      method: 'GET',
    });

    return {
      orders: Array.isArray(data.orders) ? data.orders : [],
      pagination: data.pagination || {
        page: Number(page) || 1,
        limit: Number(limit) || 25,
        total: data.orders?.length || 0,
        totalPages: 1,
      },
    };
  },

  // ============================================
  // REFUNDS API (/api/shop/me/refunds)
  // ============================================
  getRefunds: async (
    page = 1,
    limit = 25
  ): Promise<{ refunds: RefundRecord[]; pagination: Pagination }> => {
    const query = new URLSearchParams({
      page: String(Math.max(1, page)),
      limit: String(Math.min(100, Math.max(1, limit))),
    }).toString();

    const data = await apiRequest<{
      success: boolean;
      refunds: RefundRecord[];
      pagination: Pagination;
    }>(`/api/shop/me/refunds?${query}`, {
      method: 'GET',
    });

    return {
      refunds: Array.isArray(data.refunds) ? data.refunds : [],
      pagination: data.pagination || {
        page: Number(page) || 1,
        limit: Number(limit) || 25,
        total: data.refunds?.length || 0,
        totalPages: 1,
      },
    };
  },

  getRefundEligibility: async (orderId: string): Promise<RefundEligibility> => {
    const data = await apiRequest<{
      success: boolean;
      eligible: boolean;
      allowedAmount: number;
      reason: string;
      policy: any;
      expiresAt: string | null;
    }>(`/api/shop/orders/${encodeURIComponent(orderId)}/refund-eligibility`, {
      method: 'GET',
    });

    return {
      eligible: Boolean(data.eligible),
      allowedAmount: Number(data.allowedAmount) || 0,
      reason: data.reason || '',
      policy: data.policy || null,
      expiresAt: data.expiresAt || null,
    };
  },

  requestRefund: async (
    orderId: string,
    idempotencyKey: string,
    payload: { amount?: number; reason?: string; notes?: string }
  ): Promise<{ success: boolean; refund: RefundRecord }> => {
    return await apiRequest<{ success: boolean; refund: RefundRecord }>(
      `/api/shop/orders/${encodeURIComponent(orderId)}/refund`,
      {
        method: 'POST',
        idempotencyKey,
        body: JSON.stringify(payload),
      }
    );
  },

  // ============================================
  // SUBSCRIPTIONS API (/api/shop/me/subscriptions)
  // ============================================
  getSubscriptions: async (): Promise<CustomerSubscription[]> => {
    const data = await apiRequest<{
      success: boolean;
      subscriptions: CustomerSubscription[];
    }>('/api/shop/me/subscriptions', {
      method: 'GET',
    });
    return Array.isArray(data.subscriptions) ? data.subscriptions : [];
  },

  updateSubscriptionCancellation: async (
    entitlementId: string,
    cancelAtPeriodEnd: boolean
  ): Promise<{ success: boolean; subscription: CustomerSubscription }> => {
    return await apiRequest<{ success: boolean; subscription: CustomerSubscription }>(
      `/api/shop/me/subscriptions/${encodeURIComponent(entitlementId)}/cancellation`,
      {
        method: 'PATCH',
        body: JSON.stringify({ cancelAtPeriodEnd }),
      }
    );
  },

  // ============================================
  // STORE CREDIT API (/api/shop/me/credit)
  // ============================================
  getCreditBalance: async (): Promise<StoreCreditBalance> => {
    const data = await apiRequest<{
      success: boolean;
      credit: StoreCreditBalance;
    }>('/api/shop/me/credit/balance', {
      method: 'GET',
    });
    return data.credit || { balance: 0, currency: 'IRR' };
  },

  getCreditTransactions: async (): Promise<StoreCreditTransaction[]> => {
    const data = await apiRequest<{
      success: boolean;
      transactions: StoreCreditTransaction[];
    }>('/api/shop/me/credit/transactions', {
      method: 'GET',
    });
    return Array.isArray(data.transactions) ? data.transactions : [];
  },

  topUpCredit: async (
    idempotencyKey: string,
    payload: { amount: number; currency: 'IRR' | 'IRT' | string; destination?: 'store_credit' }
  ): Promise<{ success: boolean; topUpId: string; payment: any; redirectUrl?: string; redirect?: string }> => {
    return await apiRequest<{
      success: boolean;
      topUpId: string;
      payment: any;
      redirectUrl?: string;
      redirect?: string;
    }>('/api/shop/me/credit/top-ups', {
      method: 'POST',
      idempotencyKey,
      body: JSON.stringify({
        amount: Math.round(Number(payload.amount)),
        currency: payload.currency,
        destination: payload.destination || 'store_credit',
      }),
    });
  },

  // ============================================
  // DOWNLOADS API (/api/shop/me/downloads)
  // ============================================
  getDownloadUrl: async (
    entitlementId: string,
    downloadId: string
  ): Promise<ProductDownloadLink> => {
    const data = await apiRequest<{
      success: boolean;
      url: string;
      expiresIn: number;
      fileName: string | null;
    }>(
      `/api/shop/me/downloads/${encodeURIComponent(entitlementId)}/${encodeURIComponent(downloadId)}`,
      {
        method: 'GET',
      }
    );

    return {
      url: data.url,
      expiresIn: data.expiresIn,
      fileName: data.fileName,
    };
  },
};
