import React from 'react';

// Map of canonical asset keys to their generated responsive widths
const RESPONSIVE_IMAGE_CONFIG: Record<
  string,
  {
    widths: number[];
    aspectRatio: string;
    defaultWidth: number;
    defaultHeight: number;
  }
> = {
  course_quant_web_masterclass: {
    widths: [400, 640, 960, 1200],
    aspectRatio: '4/3',
    defaultWidth: 403,
    defaultHeight: 302,
  },
  product_commerce_system: {
    widths: [400, 640, 960, 1200],
    aspectRatio: '4/3',
    defaultWidth: 403,
    defaultHeight: 302,
  },
  product_quant_engine: {
    widths: [400, 640, 960, 1200],
    aspectRatio: '4/3',
    defaultWidth: 403,
    defaultHeight: 302,
  },
  product_saas_architecture: {
    widths: [400, 640, 960, 1200],
    aspectRatio: '4/3',
    defaultWidth: 403,
    defaultHeight: 302,
  },
  store_hero_showcase: {
    widths: [480, 768, 1024, 1360],
    aspectRatio: '16/10',
    defaultWidth: 568,
    defaultHeight: 355,
  },
};

export function getResponsiveAssetKey(src: string): string | null {
  if (!src) return null;
  for (const key of Object.keys(RESPONSIVE_IMAGE_CONFIG)) {
    if (src.includes(key)) {
      return key;
    }
  }
  return null;
}

export interface ResponsiveStoreImageProps
  extends Omit<React.ImgHTMLAttributes<HTMLImageElement>, 'srcSet'> {
  src: string;
  alt: string;
  sizes?: string;
  priority?: boolean;
  aspectRatioClass?: string;
}

export const ResponsiveStoreImage: React.FC<ResponsiveStoreImageProps> = ({
  src,
  alt,
  sizes = '(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 403px',
  priority = false,
  className = '',
  aspectRatioClass,
  width,
  height,
  onError,
  ...rest
}) => {
  const [hasError, setHasError] = React.useState(false);
  const assetKey = getResponsiveAssetKey(src);

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    setHasError(true);
    if (onError) {
      onError(e);
    }
  };

  if (!assetKey || hasError) {
    return (
      <img
        src={src}
        alt={alt}
        loading={priority ? 'eager' : 'lazy'}
        fetchPriority={priority ? 'high' : 'auto'}
        decoding="async"
        className={className}
        width={width}
        height={height}
        onError={onError}
        {...rest}
      />
    );
  }

  const config = RESPONSIVE_IMAGE_CONFIG[assetKey];
  const renderedWidth = width ?? config.defaultWidth;
  const renderedHeight = height ?? config.defaultHeight;

  const avifSrcSet = config.widths
    .map(w => `/images/optimized/${assetKey}-${w}.avif ${w}w`)
    .join(', ');

  const webpSrcSet = config.widths
    .map(w => `/images/optimized/${assetKey}-${w}.webp ${w}w`)
    .join(', ');

  return (
    <picture className={aspectRatioClass || 'block w-full h-full'}>
      <source type="image/avif" srcSet={avifSrcSet} sizes={sizes} />
      <source type="image/webp" srcSet={webpSrcSet} sizes={sizes} />
      <img
        src={src}
        alt={alt}
        width={renderedWidth}
        height={renderedHeight}
        loading={priority ? 'eager' : 'lazy'}
        fetchPriority={priority ? 'high' : 'auto'}
        decoding="async"
        className={className}
        onError={handleImageError}
        {...rest}
      />
    </picture>
  );
};

export default ResponsiveStoreImage;
