import { getApiOrigin } from './config';
import { ApiError } from '../types';

/**
 * Creates or retrieves a correlation ID for tracing.
 */
export function getOrCreateCorrelationId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `req-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
}

export interface RequestOptions extends RequestInit {
  idempotencyKey?: string;
  skipErrorNormalization?: boolean;
}

/**
 * Standard HTTP transport client adhering to FRONTEND_ARCHITECTURE.md & API_INTEGRATION_MAP.md.
 * - Always includes credentials: 'include' (cookie-based session).
 * - Captures server-generated X-Correlation-ID from responses without transmitting custom headers in outgoing requests.
 * - Supports Idempotency-Key headers where required.
 * - Normalizes backend error envelopes preserving HTTP status and backend details.
 */
export async function apiRequest<T = any>(
  endpointPath: string,
  options: RequestOptions = {}
): Promise<T> {
  const origin = getApiOrigin();
  const normalizedPath = endpointPath.startsWith('/') ? endpointPath : `/${endpointPath}`;
  const url = `${origin}${normalizedPath}`;

  const correlationId = getOrCreateCorrelationId();
  const headers: Record<string, string> = {
    Accept: 'application/json',
    ...(options.headers as Record<string, string> || {}),
  };

  // Ensure X-Correlation-ID is not sent in outgoing requests (server generates it; not in CORS allowed headers)
  delete headers['X-Correlation-ID'];
  delete headers['x-correlation-id'];

  if (options.body && typeof options.body === 'string' && !headers['Content-Type']) {
    headers['Content-Type'] = 'application/json';
  }

  if (options.idempotencyKey) {
    headers['Idempotency-Key'] = options.idempotencyKey.trim();
  }

  const fetchOptions: RequestInit = {
    ...options,
    credentials: 'include',
    headers,
  };

  let response: Response;
  try {
    response = await fetch(url, fetchOptions);

    // Fallback if primary /api/shop route returns 404 and can be aliased without /api
    if (response.status === 404 && endpointPath.startsWith('/api/shop')) {
      const aliasPath = endpointPath.replace(/^\/api\/shop/, '/shop');
      const aliasUrl = `${origin}${aliasPath}`;
      const aliasRes = await fetch(aliasUrl, fetchOptions);
      if (aliasRes.status !== 404) {
        response = aliasRes;
      }
    }
  } catch (err: any) {
    const networkError: ApiError & { status: number } = {
      success: false,
      error: 'Network connection failed or server is unreachable.',
      message: err?.message || 'Network error',
      code: 'NETWORK_ERROR',
      correlationId,
      status: 0,
    };
    throw networkError;
  }

  const responseCorrelationId =
    response.headers.get('X-Correlation-ID') ||
    response.headers.get('x-correlation-id') ||
    correlationId;

  if (response.status === 204) {
    return {} as T;
  }

  let data: any = null;
  const contentType = response.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    try {
      data = await response.json();
    } catch {
      data = null;
    }
  } else {
    try {
      data = await response.text();
    } catch {
      data = null;
    }
  }

  if (!response.ok) {
    const errorPayload: ApiError & { status: number } = {
      success: false,
      status: response.status,
      correlationId: responseCorrelationId,
      error:
        typeof data === 'object' && data !== null
          ? data.error || data.message || `Request failed with status ${response.status}`
          : String(data || `Request failed with status ${response.status}`),
      message:
        typeof data === 'object' && data !== null
          ? data.message || data.error
          : undefined,
      code: typeof data === 'object' && data !== null ? data.code || data.errorCode : undefined,
      details: typeof data === 'object' && data !== null && Array.isArray(data.details) ? data.details : undefined,
    };
    throw errorPayload;
  }

  return data as T;
}

/**
 * Downloads a binary stream or file (e.g., CSV reports).
 */
export async function apiRequestBlob(
  endpointPath: string,
  options: RequestOptions = {}
): Promise<{ blob: Blob; filename?: string }> {
  const origin = getApiOrigin();
  const normalizedPath = endpointPath.startsWith('/') ? endpointPath : `/${endpointPath}`;
  const url = `${origin}${normalizedPath}`;

  const correlationId = getOrCreateCorrelationId();
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string> || {}),
  };

  delete headers['X-Correlation-ID'];
  delete headers['x-correlation-id'];

  const response = await fetch(url, {
    ...options,
    credentials: 'include',
    headers,
  });

  if (!response.ok) {
    let errText = 'Failed to download report';
    try {
      const errJson = await response.json();
      errText = errJson.error || errJson.message || errText;
    } catch {
      errText = await response.text().catch(() => errText);
    }
    const responseCorrelationId =
      response.headers.get('X-Correlation-ID') ||
      response.headers.get('x-correlation-id') ||
      correlationId;
    throw {
      status: response.status,
      error: errText,
      correlationId: responseCorrelationId,
    };
  }

  const disposition = response.headers.get('Content-Disposition') || '';
  let filename: string | undefined = undefined;
  const filenameMatch = disposition.match(/filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/);
  if (filenameMatch && filenameMatch[1]) {
    filename = filenameMatch[1].replace(/['"]/g, '').trim();
  }

  const blob = await response.blob();
  return { blob, filename };
}
