// --- Canonical Commerce Data Models (DATA_MODELS.md) ---

export type Currency = 'IRR' | 'IRT';
export type ItemType = 'product' | 'bundle' | 'course' | 'subscription';

export interface Page<T> {
  items: T[];
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface Pagination {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
  skip?: number;
}

export type CatalogStatus =
  | 'draft'
  | 'review'
  | 'published'
  | 'out_of_stock'
  | 'backorder'
  | 'archived'
  | 'discontinued';

export interface ProductDownloadItem {
  downloadId: string;
  key?: string;
  fileName?: string;
  fileSize?: number;
  contentType?: string;
  active?: boolean;
}

export interface ProductVariant {
  id?: string;
  _id?: string;
  name: string;
  sku?: string;
  slug?: string;
  price?: number;
  originalPrice?: number;
  currency?: Currency;
  image?: string;
  isActive?: boolean;
  attributes?: Array<{ label: string; value: string }>;
  description?: string;
  trackInventory?: boolean;
}

export interface ArchitectureSpec {
  label: string;
  value: string;
}

export interface FileTreeManifestItem {
  path: string;
  type: 'file' | 'folder';
  size?: string;
  description?: string;
}

export interface ChangelogItem {
  version: string;
  date: string;
  highlights: string[];
}

export interface CatalogItem {
  id: string; // backend _id; request ID or slug
  slug?: string;
  type: ItemType;
  title: string;
  description: string;
  subtitle?: string;
  image?: string;
  images?: string[];
  price: number; // integer smallest configured currency unit
  originalPrice?: number;
  currency: Currency;
  category?: string;
  domain?: string;
  tags?: string[];
  features?: string[];
  rating: number;
  reviewsCount: number;
  owned?: boolean; // product list/detail only; absent for guests
  isActive?: boolean;
}

export interface CourseLesson {
  id: string;
  title: string;
  duration: string;
  videoUrl?: string;
  isPreviewFree?: boolean;
  order?: number;
  isCompleted?: boolean;
}

export interface CourseModule {
  id: string;
  title: string;
  order?: number;
  lessons: CourseLesson[];
}

export interface Course extends CatalogItem {
  type: 'course';
  instructor?: string | { email?: string; firstName?: string; lastName?: string; name?: string };
  level?: string;
  content?: CourseModule[];
  curriculum?: unknown[];
}

export interface BundleComponent {
  itemType: 'product' | 'course';
  itemId: string;
  item?: CatalogItem | null;
  variantId?: string;
  quantity?: number;
}

export interface Bundle extends CatalogItem {
  type: 'bundle';
  items?: string[];
  components: BundleComponent[];
  discount?: number;
}

export interface SubscriptionPlan extends CatalogItem {
  type: 'subscription';
  billingCycle?: 'monthly' | 'quarterly' | 'yearly';
  period?: '/month' | '/quarter' | '/year';
  features: string[];
  autoRenew?: boolean;
  trialDays?: number;
  maxUsers?: number;
  maxSeats?: number;
}

export interface Product extends CatalogItem {
  type: 'product';
  sku?: string;
  status?: CatalogStatus;
  visibility?: 'hidden' | 'catalog' | 'search' | 'featured';
  variants?: ProductVariant[];
  downloads?: ProductDownloadItem[];
  refundPolicy?: Partial<RefundPolicy>;
  trackInventory?: boolean;
  stock?: number;
  fileTree?: FileTreeManifestItem[];
  changelog?: ChangelogItem[];
  architectureSpecs?: ArchitectureSpec[];
}

// Backward compatibility alias for UI components
export type ShopProduct = Omit<Product, 'type' | 'currency' | 'reviewsCount'> & {
  type: ItemType | 'digital' | string;
  currency?: Currency;
  reviewsCount?: number;
  reviews?: number; // legacy alias for reviewsCount
  authorId?: string;
  seatAllocation?: string;
  version?: string;
  releaseDate?: string;
  updatedAt?: string;
  discount?: number;
  items?: string[];
  rawItems?: any[];
  components?: any[];
  content?: CourseModule[];
  period?: '/month' | '/quarter' | '/year';
  billingInterval?: 'monthly' | 'quarterly' | 'annual';
  billingCycle?: 'monthly' | 'quarterly' | 'yearly';
  features?: string[];
  curriculum?: unknown[];
  instructor?: string | { email?: string; firstName?: string; lastName?: string; name?: string };
  level?: string;
  trialDays?: number;
  maxUsers?: number;
  maxSeats?: number;
  autoRenew?: boolean;
  recommended?: boolean;
  licenseType?: string;
};

