export type OrderStatus =
  | 'CREATED'
  | 'PENDING_PAYMENT'
  | 'REDIRECTED'
  | 'REQUEST_UNKNOWN'
  | 'PAID'
  | 'PARTIALLY_REFUNDED'
  | 'PROCESSING'
  | 'PARTIALLY_FULFILLED'
  | 'SHIPPED'
  | 'DELIVERED'
  | 'CANCELLED'
  | 'REFUNDED'
  | 'FULFILLMENT_FAILED'
  | 'FAILED';

export type FulfillmentStatus = 'NOT_READY' | 'PENDING' | 'PROCESSING' | 'COMPLETED' | 'FAILED';

export interface RefundPolicy {
  allowed: boolean;
  fullRefund: boolean;
  partialRefund: boolean;
  refundWindowHours: number;
  cancellationWindowHours: number;
  digitalAccessRevoked: boolean;
  paymentRefund: boolean;
  storeCredit: boolean;
  conditions: string[];
  exclusions: string[];
  returnRequired: boolean;
  returnShippingResponsibility: string;
}

export interface OrderLine {
  itemType: ItemType;
  itemId: string;
  name: string;
  quantity: number;
  image?: string;
  variantId?: string;
  variantName?: string;
  variantSku?: string;
  unitAmount: number;
  lineAmount: number;
  currency?: Currency;
  refundPolicy?: RefundPolicy;
  bundleProducts?: Array<{ itemType: 'product' | 'course'; itemId: string; name: string; quantity: number }>;
}

export interface CustomerOrder {
  orderId: string;
  id?: string; // backwards compatibility alias for orderId
  status: OrderStatus;
  currency: Currency;
  totalAmount: number;
  total?: number; // backwards compatibility alias for totalAmount
  items: OrderLine[];
  paymentId?: string;
  fulfillmentStatus: FulfillmentStatus;
  shipping?: {
    carrier?: string;
    trackingNumber?: string;
    shippedAt?: string;
    deliveredAt?: string;
    events?: Array<{ status: 'SHIPPED' | 'DELIVERED'; carrier?: string; trackingNumber?: string; createdAt: string }>;
  };
  createdAt: string;
  date?: string; // backwards compatibility alias for createdAt
  paidAt?: string;
  fulfilledAt?: string;
  refundAmount?: number;
}

export type ShopOrder = CustomerOrder; // Alias for compatibility

