import React, { useState } from 'react';
import { Download, Smartphone, X, Share } from 'lucide-react';
import { usePWAInstall } from '../hooks/usePWAInstall';

export const PWAInstallButton: React.FC<{ compact?: boolean }> = ({ compact = false }) => {
  const { isInstallable, isInstalled, isIOS, install } = usePWAInstall();
  const [showIOSGuide, setShowIOSGuide] = useState(false);

  // Strict guarantee: Never show install button if already installed or running in standalone mode
  if (isInstalled) {
    return null;
  }

  // Chromium / Android / Desktop native install prompt flow
  if (isInstallable) {
    return (
      <button
        type="button"
        onClick={install}
        title="Install Quader Store App for offline access & instant loading"
        className={`h-10 ${
          compact ? 'px-3' : 'px-3.5'
        } rounded-lg border border-emerald-600/40 dark:border-emerald-500/40 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-600 hover:text-white dark:hover:bg-emerald-500 dark:hover:text-slate-950 transition-colors flex items-center gap-2 text-xs font-semibold whitespace-nowrap shrink-0`}
      >
        <Download size={14} />
        <span>Install App</span>
      </button>
    );
  }

  // iOS Safari flow (WebKit does not fire beforeinstallprompt)
  if (isIOS) {
    return (
      <>
        <button
          type="button"
          onClick={() => setShowIOSGuide(true)}
          className="h-10 px-3 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white/60 dark:bg-[#111318] text-slate-700 dark:text-slate-300 hover:border-emerald-600 transition-colors flex items-center gap-1.5 text-xs font-semibold whitespace-nowrap shrink-0"
        >
          <Smartphone size={14} className="text-emerald-600 dark:text-emerald-400" />
          <span>Install App</span>
        </button>

        {showIOSGuide && (
          <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/60 backdrop-blur-xs p-4">
            <div className="w-full max-w-sm rounded-2xl bg-[#FBFBF9] dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] p-6 shadow-2xl">
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-mono font-semibold text-emerald-600 dark:text-emerald-400">
                  iOS HOME SCREEN APP
                </span>
                <button
                  type="button"
                  onClick={() => setShowIOSGuide(false)}
                  className="p-1 text-slate-400 hover:text-slate-900 dark:hover:text-white"
                >
                  <X size={16} />
                </button>
              </div>
              <h3 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-2">
                Install Quader Store on iPhone / iPad
              </h3>
              <ol className="space-y-2.5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed mb-5">
                <li className="flex items-center gap-2">
                  <span className="w-5 h-5 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-mono font-bold flex items-center justify-center shrink-0">
                    1
                  </span>
                  <span>
                    Tap the <strong>Share</strong> icon <Share size={12} className="inline mx-0.5" /> in your Safari toolbar.
                  </span>
                </li>
                <li className="flex items-center gap-2">
                  <span className="w-5 h-5 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-mono font-bold flex items-center justify-center shrink-0">
                    2
                  </span>
                  <span>
                    Scroll down and select <strong>Add to Home Screen</strong>.
                  </span>
                </li>
              </ol>
              <button
                type="button"
                onClick={() => setShowIOSGuide(false)}
                className="w-full py-2.5 rounded-lg bg-slate-900 dark:bg-white text-white dark:text-slate-950 text-xs font-semibold"
              >
                Got It
              </button>
            </div>
          </div>
        )}
      </>
    );
  }

  return null;
};

export default PWAInstallButton;
