import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, ShoppingBag, Package, Shield, Users, 
  LogOut, ShieldCheck, User as UserIcon,
  FileCheck, Cpu, Video, Settings, Wallet
} from 'lucide-react';
import { User } from '../../types';

export type Tab = 
  | 'overview' 
  | 'orders' 
  | 'inventory' 
  | 'manage_courses' 
  | 'manage_products' 
  | 'users' 
  | 'verification' 
  | 'admin_verifications' 
  | 'admin_profiles' 
  | 'profile' 
  | 'expert_systems' 
  | 'settings' 
  | 'blog' 
  | 'liked' 
  | 'moderation';

interface DashboardSidebarProps {
  user: User;
  activeTab?: Tab;
  setActiveTab?: (tab: Tab) => void;
  onLogout: () => void;
  onNavigate?: () => void;
}

const DashboardSidebar: React.FC<DashboardSidebarProps> = ({ 
  user, 
  activeTab = 'overview', 
  setActiveTab, 
  onLogout,
  onNavigate 
}) => {
  const location = useLocation();
  const navigate = useNavigate();
  const currentPath = location.pathname;
  const isDashboard = currentPath === '/dashboard' || currentPath === '/shop/dashboard';

  const handleTabClick = (tab: Tab) => {
    if (onNavigate) onNavigate();
    if (isDashboard && setActiveTab) {
      setActiveTab(tab);
    } else {
      navigate(`/dashboard?tab=${tab}`);
    }
  };

  const isTabActive = (tab: Tab) => isDashboard && activeTab === tab;

  const itemClass = (isActive: boolean) =>
    `w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-bold transition-all ${
      isActive
        ? 'bg-emerald-600 text-white shadow-md shadow-emerald-600/20'
        : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-white'
    }`;

  const isSeller = user.role === 'admin' || user.role === 'moderator' || user.role === 'creator' || user.role === 'developer';
  const isAdminOrOps = ['admin', 'super_admin', 'manager', 'support', 'finance'].includes(user.role);

  return (
    <aside className="w-full h-full flex flex-col">
      <div className="p-6">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-12 h-12 rounded-full bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-xl overflow-hidden relative group shrink-0 border-2 border-white dark:border-slate-800">
            {user.profilePic ? (
              <img src={user.profilePic} alt="Profile" className="w-full h-full object-cover" />
            ) : (
              <span>{(user.firstName || 'U')[0]}</span>
            )}
          </div>
          <div className="overflow-hidden">
            <h3 className="font-bold text-slate-900 dark:text-white truncate text-sm" title={`${user.firstName || ''} ${user.lastName || ''}`}>
              {user.firstName} {user.lastName}
            </h3>
            <p className="text-[10px] uppercase font-black text-emerald-600 truncate tracking-wider">
              {user.role} Member
            </p>
          </div>
        </div>

        <nav className="space-y-1">
          <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Personal</h4>
          
          <button
            type="button"
            onClick={() => handleTabClick('overview')}
            className={itemClass(isTabActive('overview'))}
          >
            <LayoutDashboard size={18} />
            <span>Dashboard</span>
          </button>

          <Link
            to="/library"
            onClick={onNavigate}
            className={itemClass(currentPath === '/library')}
          >
            <Package size={18} />
            <span>Digital Library</span>
          </Link>

          <Link
            to="/orders"
            onClick={onNavigate}
            className={itemClass(currentPath.startsWith('/orders'))}
          >
            <ShoppingBag size={18} />
            <span>My Orders</span>
          </Link>

          <Link
            to="/refunds"
            onClick={onNavigate}
            className={itemClass(currentPath.startsWith('/refunds'))}
          >
            <FileCheck size={18} />
            <span>Refund History</span>
          </Link>

          <Link
            to="/credit"
            onClick={onNavigate}
            className={itemClass(currentPath.startsWith('/credit'))}
          >
            <Wallet size={18} />
            <span>Store Credit</span>
          </Link>

          <Link
            to="/subscriptions/manage"
            onClick={onNavigate}
            className={itemClass(currentPath.startsWith('/subscriptions'))}
          >
            <Cpu size={18} />
            <span>Subscriptions</span>
          </Link>

          <button
            type="button"
            onClick={() => handleTabClick('profile')}
            className={itemClass(isTabActive('profile'))}
          >
            <UserIcon size={18} />
            <span>My Profile</span>
          </button>

          <button
            type="button"
            onClick={() => handleTabClick('verification')}
            className={itemClass(isTabActive('verification'))}
          >
            <ShieldCheck size={18} />
            <span>Account ID</span>
          </button>

          {isSeller && (
            <>
              <div className="my-4 border-t border-slate-100 dark:border-slate-800"></div>
              <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Creator Studio</h4>
              
              <Link
                to="/creator/catalog"
                onClick={onNavigate}
                className={itemClass(currentPath.startsWith('/creator/catalog'))}
              >
                <Package size={18} />
                <span>Creator Catalog</span>
              </Link>

              <button
                type="button"
                onClick={() => handleTabClick('manage_courses')}
                className={itemClass(isTabActive('manage_courses'))}
              >
                <Video size={18} />
                <span>My Courses</span>
              </button>

              <button
                type="button"
                onClick={() => handleTabClick('manage_products')}
                className={itemClass(isTabActive('manage_products'))}
              >
                <Package size={18} />
                <span>My Products</span>
              </button>
            </>
          )}

          {isAdminOrOps && (
            <>
              <div className="my-4 border-t border-slate-100 dark:border-slate-800"></div>
              <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Store Operations</h4>
              
              <Link
                to="/admin"
                onClick={onNavigate}
                className={itemClass(currentPath === '/admin' || currentPath === '/admin/dashboard')}
              >
                <Shield size={18} />
                <span>Operations Hub</span>
              </Link>

              <Link
                to="/admin/orders"
                onClick={onNavigate}
                className={itemClass(currentPath === '/admin/orders')}
              >
                <ShoppingBag size={18} />
                <span>Orders Manager</span>
              </Link>

              <Link
                to="/admin/refunds"
                onClick={onNavigate}
                className={itemClass(currentPath === '/admin/refunds')}
              >
                <FileCheck size={18} />
                <span>Refunds Desk</span>
              </Link>

              <Link
                to="/admin/credit"
                onClick={onNavigate}
                className={itemClass(currentPath === '/admin/credit')}
              >
                <Wallet size={18} />
                <span>Credit Reconciliation</span>
              </Link>
            </>
          )}

          {user.role === 'admin' && (
            <>
              <div className="my-4 border-t border-slate-100 dark:border-slate-800"></div>
              <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Platform Admin</h4>
              
              <button
                type="button"
                onClick={() => handleTabClick('admin_verifications')}
                className={itemClass(isTabActive('admin_verifications'))}
              >
                <FileCheck size={18} />
                <span>ID Verifications</span>
              </button>

              <button
                type="button"
                onClick={() => handleTabClick('expert_systems')}
                className={itemClass(isTabActive('expert_systems'))}
              >
                <Cpu size={18} />
                <span>License Control</span>
              </button>

              <button
                type="button"
                onClick={() => handleTabClick('users')}
                className={itemClass(isTabActive('users'))}
              >
                <Users size={18} />
                <span>User Manager</span>
              </button>

              <button
                type="button"
                onClick={() => handleTabClick('settings')}
                className={itemClass(isTabActive('settings'))}
              >
                <Settings size={18} />
                <span>Store Settings</span>
              </button>
            </>
          )}
        </nav>
      </div>

      <div className="mt-auto p-6 border-t border-slate-100 dark:border-slate-800">
        <button 
          type="button"
          onClick={onLogout}
          className="w-full flex items-center gap-3 px-4 py-2 text-sm font-bold text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
        >
          <LogOut size={18} /> Sign Out
        </button>
      </div>
    </aside>
  );
};

export default DashboardSidebar;