import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback } from 'react';
import { User, UserRole } from '../types';
import { getApiOrigin } from '../api/config';

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  authError: string | null;
  login: (email: string, password: string, rememberMe?: boolean) => Promise<{ success: boolean; message: string }>;
  register: (firstName: string, lastName: string, email: string, password: string) => Promise<{ success: boolean; message: string }>;
  logout: () => Promise<{ success: boolean; message?: string }>;
  checkAuth: () => Promise<void>;
  hasRole: (allowedRoles: UserRole[]) => boolean;
  requestPasswordReset: (email: string) => Promise<{ success: boolean; message: string }>;
  confirmPasswordReset: (email: string, token: string, newPassword: string) => Promise<{ success: boolean; message: string }>;
  changePassword: (currentPassword: string, newPassword: string) => Promise<{ success: boolean; message: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const API_URL = getApiOrigin();

/**
 * Universal Role Permission Evaluator conforming to AUTHORIZATION_MAP.md.
 * - admin and super_admin are implicitly admitted for any staff/commerce allowed-role list.
 * - Persisted role check fails closed if role is absent.
 */
export function hasRolePermission(userRole?: UserRole | string, allowedRoles: UserRole[] = []): boolean {
  if (!userRole) return false;
  if (userRole === 'admin' || userRole === 'super_admin') return true;
  return allowedRoles.includes(userRole as UserRole);
}

const sanitizeUser = (user: User): User => {
  if (user.profilePic && !user.profilePic.startsWith('http') && user.profilePic.includes('cdn.quader864.ir')) {
    return { ...user, profilePic: `https://${user.profilePic}` };
  }
  return user;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Client auth state is strictly memory-only; never persist role or tokens to localStorage as authority
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [authError, setAuthError] = useState<string | null>(null);

  const checkAuth = useCallback(async () => {
    try {
      setAuthError(null);
      const url = `${API_URL}/auth/verify`;
      const res = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({}),
      });

      if (res.ok) {
        const data = await res.json();
        if (data.status === 'authorized' && data.user) {
          setUser(sanitizeUser(data.user));
        } else {
          setUser(null);
        }
      } else if (res.status === 401) {
        setUser(null);
      } else if (res.status === 403) {
        // Session expired (tokenVersion incremented or cookie expired)
        setUser(null);
        setAuthError('Session expired. Please sign in again.');
      } else if (res.status === 503) {
        // Database or auth service temporarily unavailable
        setAuthError('Auth service is temporarily unavailable.');
      } else {
        setUser(null);
      }
    } catch {
      // Network failure
      setUser(null);
      setAuthError('Unable to connect to authentication server.');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  const login = async (email: string, password: string, rememberMe?: boolean) => {
    try {
      setAuthError(null);
      const res = await fetch(`${API_URL}/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({ email: email.trim(), password, rememberMe }),
      });

      const data = await res.json();

      if (res.ok && data.user) {
        const sanitized = sanitizeUser(data.user);
        setUser(sanitized);
        return { success: true, message: data.message || 'Login successful' };
      } else {
        const errMessage = data.message || data.error || 'Invalid email or password';
        setAuthError(errMessage);
        return { success: false, message: errMessage };
      }
    } catch {
      const errMessage = 'Network error during login. Please try again.';
      setAuthError(errMessage);
      return { success: false, message: errMessage };
    }
  };

  const register = async (firstName: string, lastName: string, email: string, password: string) => {
    try {
      setAuthError(null);
      const res = await fetch(`${API_URL}/auth/web-register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({
          firstName: firstName.trim(),
          lastName: lastName.trim(),
          email: email.trim(),
          password,
        }),
      });

      const data = await res.json();

      if (res.ok) {
        // Blueprint: Registration sets cookie but response omits user; hydrate user via /auth/verify
        await checkAuth();
        return { success: true, message: data.message || 'Registration successful' };
      } else {
        const errMessage = data.message || data.error || 'Registration failed';
        setAuthError(errMessage);
        return { success: false, message: errMessage };
      }
    } catch {
      const errMessage = 'Network error during registration. Please try again.';
      setAuthError(errMessage);
      return { success: false, message: errMessage };
    }
  };

  const logout = async () => {
    try {
      const res = await fetch(`${API_URL}/auth/logout`, {
        method: 'POST',
        credentials: 'include',
      });
      if (res.status === 503) {
        return { success: false, message: 'Session revocation unavailable on server. Please retry.' };
      }
    } catch {
      // best-effort
    } finally {
      setUser(null);
    }
    return { success: true };
  };

  const hasRole = useCallback(
    (allowedRoles: UserRole[]): boolean => {
      return hasRolePermission(user?.role, allowedRoles);
    },
    [user]
  );

  const requestPasswordReset = async (email: string) => {
    try {
      const res = await fetch(`${API_URL}/auth/password-recovery/send-link`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: JSON.stringify({ email: email.trim() }),
      });

      const data = await res.json();
      if (res.ok || data.success) {
        return { success: true, message: data.message || 'If an account exists, a recovery link has been sent.' };
      }
      return { success: false, message: data.error || data.message || 'Failed to send recovery link' };
    } catch (err: any) {
      return { success: false, message: err?.message || 'Network error' };
    }
  };

  const confirmPasswordReset = async (email: string, token: string, newPassword: string) => {
    try {
      const res = await fetch(`${API_URL}/auth/password-recovery/reset`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: JSON.stringify({ email: email.trim(), token: token.trim(), newPassword }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        return { success: true, message: data.message || 'Password reset successfully' };
      }
      return { success: false, message: data.error || data.message || 'Failed to reset password' };
    } catch (err: any) {
      return { success: false, message: err?.message || 'Network error' };
    }
  };

  const changePassword = async (currentPassword: string, newPassword: string) => {
    try {
      const res = await fetch(`${API_URL}/auth/password-change`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({ currentPassword, newPassword }),
      });

      const data = await res.json();
      if (res.ok) {
        return { success: true, message: data.message || 'Password changed successfully' };
      }
      return { success: false, message: data.error || data.message || 'Failed to change password' };
    } catch (err: any) {
      return { success: false, message: err?.message || 'Network error' };
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isLoading,
        authError,
        login,
        register,
        logout,
        checkAuth,
        hasRole,
        requestPasswordReset,
        confirmPasswordReset,
        changePassword,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

const defaultAuthContext: AuthContextType = {
  user: null,
  isLoading: false,
  authError: null,
  login: async () => ({ success: false, message: 'No auth provider' }),
  register: async () => ({ success: false, message: 'No auth provider' }),
  logout: async () => ({ success: true }),
  checkAuth: async () => {},
  hasRole: () => false,
  requestPasswordReset: async () => ({ success: false, message: 'No auth provider' }),
  confirmPasswordReset: async () => ({ success: false, message: 'No auth provider' }),
  changePassword: async () => ({ success: false, message: 'No auth provider' }),
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    return defaultAuthContext;
  }
  return context;
};
