import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useShop } from '../context/ShopContext';

export const DEFAULT_SEO_TITLE = 'Quader Store – Web Systems & Quantitative Trading Tools';
export const DEFAULT_SEO_DESCRIPTION =
  'Explore production-ready web systems, full-stack SaaS kits, and quantitative MQL5 trading engines by Alireza Kiani (Quader). Deploy with source access.';
export const DEFAULT_OG_IMAGE = '/og-image.png';
export const SITE_NAME = 'Quader Store';

function upsertMetaTag(
  attrName: 'name' | 'property',
  attrValue: string,
  content: string
): void {
  if (typeof document === 'undefined') return;
  let el = document.head.querySelector<HTMLMetaElement>(
    `meta[${attrName}="${attrValue}"]`
  );
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute(attrName, attrValue);
    document.head.appendChild(el);
  }
  el.setAttribute('content', content);
}

function upsertLinkTag(rel: string, href: string): void {
  if (typeof document === 'undefined') return;
  let el = document.head.querySelector<HTMLLinkElement>(`link[rel="${rel}"]`);
  if (!el) {
    el = document.createElement('link');
    el.setAttribute('rel', rel);
    document.head.appendChild(el);
  }
  el.setAttribute('href', href);
}

function upsertRouteJsonLd(schemaData: Record<string, any> | null): void {
  if (typeof document === 'undefined') return;
  const scriptId = 'quader-route-jsonld';
  let scriptEl = document.getElementById(scriptId) as HTMLScriptElement | null;

  if (!schemaData) {
    if (scriptEl) {
      scriptEl.remove();
    }
    return;
  }

  if (!scriptEl) {
    scriptEl = document.createElement('script');
    scriptEl.id = scriptId;
    scriptEl.type = 'application/ld+json';
    document.head.appendChild(scriptEl);
  }
  scriptEl.textContent = JSON.stringify(schemaData);
}

function resolveAbsoluteUrl(origin: string, pathOrUrl: string): string {
  if (!pathOrUrl) return `${origin}${DEFAULT_OG_IMAGE}`;
  if (/^https?:\/\//i.test(pathOrUrl)) return pathOrUrl;
  const normalizedPath = pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`;
  return `${origin}${normalizedPath}`;
}

function truncateText(text: string, maxLength: number): string {
  const clean = text.replace(/\s+/g, ' ').trim();
  if (clean.length <= maxLength) return clean;
  return `${clean.slice(0, maxLength - 1).trimEnd()}…`;
}

const PRIVATE_NOINDEX_PREFIXES = [
  '/checkout',
  '/shop/checkout',
  '/payment-success',
  '/payment-pending',
  '/payment-failed',
  '/dashboard',
  '/shop/dashboard',
  '/admin',
  '/auth',
  '/password-reset',
  '/blog/editor',
];

const SEOHead: React.FC = () => {
  const location = useLocation();
  const { allCatalogItems, reviews } = useShop();

  useEffect(() => {
    if (typeof window === 'undefined' || typeof document === 'undefined') return;

    const origin = window.location.origin || 'https://store.quader864.ir';
    const pathname = location.pathname || '/';
    const canonicalUrl = `${origin}${pathname}`;

    const isPrivateRoute = PRIVATE_NOINDEX_PREFIXES.some(
      prefix => pathname === prefix || pathname.startsWith(`${prefix}/`)
    );

    const robotsDirective = isPrivateRoute
      ? 'noindex, nofollow'
      : 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1';

    let title = DEFAULT_SEO_TITLE;
    let description = DEFAULT_SEO_DESCRIPTION;
    let ogType = 'website';
    let imagePath = DEFAULT_OG_IMAGE;
    let keywords =
      'Quader Store, Alireza Kiani, MQL5 trading systems, quantitative trading tools, SaaS starter kit, React 19 architecture, algorithmic trading, XAUUSD EA, full-stack web systems';
    let priceAmount: string | null = null;
    let dynamicSchema: Record<string, any> | null = null;

    const catalogList = allCatalogItems;

    // 1. Product / Course / Bundle Detail Route: /item/:id
    if (pathname.startsWith('/item/')) {
      const itemId = decodeURIComponent(pathname.replace('/item/', '').split('/')[0]);
      const product = catalogList.find(p => p.id === itemId || p.slug === itemId);

      if (product) {
        const shortTitle = truncateText(product.title, 42);
        title = `${shortTitle} | Quader Store`;
        description = truncateText(
          `${product.description} Includes complete source code, architecture documentation, and commercial license ($${product.price} USD).`,
          158
        );
        ogType = 'product';
        imagePath = product.image || DEFAULT_OG_IMAGE;
        priceAmount = String(product.price);
        if (product.tags && product.tags.length > 0) {
          keywords = `${product.title}, ${product.tags.join(', ')}, Quader Store, Alireza Kiani`;
        }

        const itemReviews = reviews[product.id] || [];
        const reviewSchemas = itemReviews.slice(0, 5).map(r => ({
          '@type': 'Review',
          author: {
            '@type': 'Person',
            name: r.userName || (r as any).user || 'Verified Engineer',
          },
          datePublished: r.date,
          reviewBody: r.content || (r as any).comment || '',
          reviewRating: {
            '@type': 'Rating',
            ratingValue: String(r.rating),
            bestRating: '5',
            worstRating: '1',
          },
        }));

        const offerSchema = {
          '@type': 'Offer',
          url: canonicalUrl,
          priceCurrency: 'USD',
          price: String(product.price),
          availability: 'https://schema.org/InStock',
          seller: {
            '@type': 'Organization',
            name: SITE_NAME,
          },
        };

        const aggregateRatingSchema = {
          '@type': 'AggregateRating',
          ratingValue: String(product.rating || 4.9),
          reviewCount: String(Math.max(product.reviews || 12, itemReviews.length || 1)),
          bestRating: '5',
          worstRating: '1',
        };

        const primaryEntity =
          product.type === 'course'
            ? {
                '@type': 'Course',
                name: product.title,
                description: product.description,
                url: canonicalUrl,
                image: resolveAbsoluteUrl(origin, imagePath),
                provider: {
                  '@type': 'Organization',
                  name: SITE_NAME,
                  sameAs: origin,
                },
                offers: offerSchema,
                aggregateRating: aggregateRatingSchema,
              }
            : {
                '@type': ['Product', 'SoftwareApplication'],
                name: product.title,
                description: product.description,
                image: resolveAbsoluteUrl(origin, imagePath),
                sku: product.id,
                brand: {
                  '@type': 'Brand',
                  name: SITE_NAME,
                },
                applicationCategory:
                  product.tags?.some(t => /mql5|quant|xauusd|mt5/i.test(t))
                    ? 'FinanceApplication'
                    : 'DeveloperApplication',
                operatingSystem: 'Web, Windows, macOS, Linux, MetaTrader 5',
                offers: offerSchema,
                aggregateRating: aggregateRatingSchema,
                ...(reviewSchemas.length > 0 ? { review: reviewSchemas } : {}),
              };

        dynamicSchema = {
          '@context': 'https://schema.org',
          '@graph': [
            {
              '@type': 'BreadcrumbList',
              itemListElement: [
                {
                  '@type': 'ListItem',
                  position: 1,
                  name: 'Store Catalog',
                  item: `${origin}/`,
                },
                {
                  '@type': 'ListItem',
                  position: 2,
                  name:
                    product.type === 'course'
                      ? 'Masterclasses'
                      : product.type === 'bundle'
                        ? 'System Bundles'
                        : 'Software Systems',
                  item: `${origin}/${
                    product.type === 'course'
                      ? 'courses'
                      : product.type === 'bundle'
                        ? 'bundles'
                        : 'products'
                  }`,
                },
                {
                  '@type': 'ListItem',
                  position: 3,
                  name: product.title,
                  item: canonicalUrl,
                },
              ],
            },
            primaryEntity,
          ],
        };
      }
    }
    // 2. Category Routes: /products, /courses, /bundles, /subscriptions, /shop/:category
    else if (
      pathname === '/products' ||
      pathname === '/courses' ||
      pathname === '/bundles' ||
      pathname === '/subscriptions' ||
      pathname.startsWith('/shop/')
    ) {
      const catSlug = pathname.replace('/shop/', '').replace(/^\//, '');
      const categoryMeta: Record<
        string,
        { title: string; desc: string; filterType?: string }
      > = {
        products: {
          title: 'Software Systems & MQL5 Engines – Quader Store',
          desc: 'Browse production-ready web architectures, multi-tenant SaaS kits, and institutional MQL5 trading systems with full source code.',
          filterType: 'digital',
        },
        courses: {
          title: 'Engineering & Quant Masterclasses – Quader Store',
          desc: 'Master full-stack distributed web architecture and algorithmic MQL5 trading systems with hands-on laboratory codebases.',
          filterType: 'course',
        },
        bundles: {
          title: 'Full-Stack & Quant System Bundles – Quader Store',
          desc: 'Save up to 35% with curated studio bundles combining production web architectures, MQL5 trading engines, and masterclasses.',
          filterType: 'bundle',
        },
        subscriptions: {
          title: 'Studio Retainers & Subscriptions – Quader Store',
          desc: 'Subscribe for continuous access to all Quader Store software releases, quantitative execution updates, and priority reviews.',
        },
      };

      const matched = categoryMeta[catSlug] || categoryMeta.products;
      title = matched.title;
      description = matched.desc;

      const filteredItems = matched.filterType
        ? catalogList.filter(item => item.type === matched.filterType)
        : catalogList;

      dynamicSchema = {
        '@context': 'https://schema.org',
        '@graph': [
          {
            '@type': 'BreadcrumbList',
            itemListElement: [
              {
                '@type': 'ListItem',
                position: 1,
                name: 'Store Catalog',
                item: `${origin}/`,
              },
              {
                '@type': 'ListItem',
                position: 2,
                name: matched.title.split('–')[0].trim(),
                item: canonicalUrl,
              },
            ],
          },
          {
            '@type': 'CollectionPage',
            name: matched.title,
            description: matched.desc,
            url: canonicalUrl,
            mainEntity: {
              '@type': 'ItemList',
              numberOfItems: filteredItems.length,
              itemListElement: filteredItems.map((item, idx) => ({
                '@type': 'ListItem',
                position: idx + 1,
                url: `${origin}/item/${item.id}`,
                name: item.title,
              })),
            },
          },
        ],
      };
    }
    // 3. Engineering Journal / Blog Routes
    else if (pathname === '/blog' || pathname.startsWith('/blog/')) {
      const slug = pathname.replace('/blog', '').replace(/^\//, '');
      if (!slug) {
        title = 'Engineering Journal & Quant Research – Quader Store';
        description =
          'Deep-dive technical articles on distributed web systems, SaaS engineering, and algorithmic MQL5 market microstructure.';
      } else {
        const readableTitle = slug
          .split('-')
          .map(w => w.charAt(0).toUpperCase() + w.slice(1))
          .join(' ');
        title = `${truncateText(readableTitle, 42)} | Quader Journal`;
        description = truncateText(
          `Technical architecture breakdown and implementation notes on ${readableTitle} by Alireza Kiani (Quader).`,
          156
        );
        ogType = 'article';
      }

      dynamicSchema = {
        '@context': 'https://schema.org',
        '@type': slug ? 'TechArticle' : 'Blog',
        headline: title,
        description,
        url: canonicalUrl,
        author: {
          '@type': 'Person',
          name: 'Alireza Kiani (Quader)',
          url: 'https://quader864.ir',
        },
        publisher: {
          '@type': 'Organization',
          name: SITE_NAME,
          logo: {
            '@type': 'ImageObject',
            url: `${origin}/store-q-logo.svg`,
          },
        },
      };
    }
    // 4. Checkout & Payment Result Routes (noindex)
    else if (pathname === '/checkout' || pathname === '/shop/checkout') {
      title = 'Secure Checkout – Quader Store';
      description =
        'Complete your Quader Store order via server-verified ZarinPal settlement for instant repository and commercial license provisioning.';
    } else if (
      pathname === '/payment-success' ||
      pathname === '/payment-pending' ||
      pathname === '/payment-failed'
    ) {
      title = 'Payment Verification Status – Quader Store';
      description =
        'Authenticated server-side payment verification status for your Quader Store software license order.';
    } else if (pathname.startsWith('/dashboard') || pathname.startsWith('/shop/dashboard')) {
      title = 'Client & Studio Dashboard – Quader Store';
      description =
        'Access your provisioned software repositories, commercial license keys, and engineering masterclasses.';
    }
    // 5. Home Storefront (/ or /shop)
    else {
      title = DEFAULT_SEO_TITLE;
      description = DEFAULT_SEO_DESCRIPTION;
      dynamicSchema = {
        '@context': 'https://schema.org',
        '@type': 'ItemList',
        name: 'Quader Store Flagship Software Systems & Masterclasses',
        numberOfItems: catalogList.length,
        itemListElement: catalogList.map((item, idx) => ({
          '@type': 'ListItem',
          position: idx + 1,
          item: {
            '@type': 'Product',
            name: item.title,
            description: item.description,
            image: resolveAbsoluteUrl(origin, item.image || DEFAULT_OG_IMAGE),
            url: `${origin}/item/${item.id}`,
            sku: item.id,
            brand: {
              '@type': 'Brand',
              name: SITE_NAME,
            },
            offers: {
              '@type': 'Offer',
              priceCurrency: 'USD',
              price: String(item.price),
              availability: 'https://schema.org/InStock',
              url: `${origin}/item/${item.id}`,
            },
            aggregateRating: {
              '@type': 'AggregateRating',
              ratingValue: String(item.rating || 4.9),
              reviewCount: String(item.reviews || 18),
            },
          },
        })),
      };
    }

    const absoluteImageUrl = resolveAbsoluteUrl(origin, imagePath);

    // Apply document title & head tags
    document.title = title;
    upsertMetaTag('name', 'description', description);
    upsertMetaTag('name', 'keywords', keywords);
    upsertMetaTag('name', 'robots', robotsDirective);
    upsertMetaTag('name', 'googlebot', robotsDirective);
    upsertLinkTag('canonical', canonicalUrl);

    // OpenGraph tags
    upsertMetaTag('property', 'og:type', ogType);
    upsertMetaTag('property', 'og:site_name', SITE_NAME);
    upsertMetaTag('property', 'og:title', title);
    upsertMetaTag('property', 'og:description', description);
    upsertMetaTag('property', 'og:url', canonicalUrl);
    upsertMetaTag('property', 'og:image', absoluteImageUrl);
    upsertMetaTag('property', 'og:image:alt', title);

    if (priceAmount) {
      upsertMetaTag('property', 'product:price:amount', priceAmount);
      upsertMetaTag('property', 'product:price:currency', 'USD');
    }

    // Twitter / X Card tags
    upsertMetaTag('name', 'twitter:card', 'summary_large_image');
    upsertMetaTag('name', 'twitter:title', title);
    upsertMetaTag('name', 'twitter:description', description);
    upsertMetaTag('name', 'twitter:image', absoluteImageUrl);
    upsertMetaTag('name', 'twitter:image:alt', title);

    // Route-specific JSON-LD structured data
    upsertRouteJsonLd(dynamicSchema);
  }, [location.pathname, allCatalogItems, reviews]);

  return null;
};

export default SEOHead;
