import { useEffect, useState, useCallback, useRef } from 'react';
import { useRegisterSW } from 'virtual:pwa-register/react';

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }>;
}

const INSTALLED_STORAGE_KEY = 'quader_pwa_installed_v1';
const NOTIF_OPT_IN_KEY = 'quader_pwa_notifications_opt_in';

// Shared singleton state so multiple components reading usePWAInstall stay in sync
let globalDeferredPrompt: BeforeInstallPromptEvent | null = null;
const listeners = new Set<() => void>();

function notifyListeners() {
  listeners.forEach(fn => fn());
}

function checkIsStandalone(): boolean {
  if (typeof window === 'undefined') return false;
  const isStandaloneMedia =
    window.matchMedia('(display-mode: standalone)').matches ||
    window.matchMedia('(display-mode: window-controls-overlay)').matches ||
    window.matchMedia('(display-mode: fullscreen)').matches ||
    window.matchMedia('(display-mode: minimal-ui)').matches;
  const isIOSStandalone = (window.navigator as unknown as { standalone?: boolean }).standalone === true;
  const isAndroidTWA = typeof document !== 'undefined' && document.referrer.startsWith('android-app://');
  return isStandaloneMedia || isIOSStandalone || isAndroidTWA;
}

export function usePWAInstall() {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(globalDeferredPrompt);
  const [isInstalled, setIsInstalled] = useState<boolean>(() => {
    if (checkIsStandalone()) return true;
    try {
      return localStorage.getItem(INSTALLED_STORAGE_KEY) === 'true';
    } catch {
      return false;
    }
  });
  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    const syncState = () => {
      setDeferredPrompt(globalDeferredPrompt);
      if (checkIsStandalone()) {
        setIsInstalled(true);
      }
    };
    listeners.add(syncState);

    // 1. Evaluate current display mode immediately
    const standaloneNow = checkIsStandalone();
    if (standaloneNow) {
      setIsInstalled(true);
      try {
        localStorage.setItem(INSTALLED_STORAGE_KEY, 'true');
      } catch {}
    }

    // 2. Detect iOS Safari (where beforeinstallprompt is not supported)
    const ua = window.navigator.userAgent.toLowerCase();
    const isIOSDevice =
      /iphone|ipad|ipod/.test(ua) ||
      (window.navigator.platform === 'MacIntel' && window.navigator.maxTouchPoints > 1);
    setIsIOS(isIOSDevice && !standaloneNow);

    // 3. Check Chromium getInstalledRelatedApps API if supported
    const navAny = window.navigator as any;
    if (typeof navAny.getInstalledRelatedApps === 'function') {
      navAny
        .getInstalledRelatedApps()
        .then((apps: any[]) => {
          if (Array.isArray(apps) && apps.length > 0) {
            setIsInstalled(true);
            try {
              localStorage.setItem(INSTALLED_STORAGE_KEY, 'true');
            } catch {}
          }
        })
        .catch(() => {});
    }

    // 4. Listen for display-mode changes (e.g., user clicks "Open in App" in address bar)
    const mediaQuery = window.matchMedia('(display-mode: standalone)');
    const handleDisplayModeChange = (e: MediaQueryListEvent) => {
      if (e.matches) {
        globalDeferredPrompt = null;
        setIsInstalled(true);
        try {
          localStorage.setItem(INSTALLED_STORAGE_KEY, 'true');
        } catch {}
        notifyListeners();
      }
    };
    if (typeof mediaQuery.addEventListener === 'function') {
      mediaQuery.addEventListener('change', handleDisplayModeChange);
    }

    // 5. Capture beforeinstallprompt
    // Note: If the browser fires beforeinstallprompt while not in standalone mode,
    // it means the app is currently NOT installed on this device (or was uninstalled).
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      if (checkIsStandalone()) return;
      globalDeferredPrompt = e as BeforeInstallPromptEvent;
      try {
        localStorage.removeItem(INSTALLED_STORAGE_KEY);
      } catch {}
      setIsInstalled(false);
      notifyListeners();
    };

    // 6. Capture appinstalled event so the install button disappears immediately
    const handleAppInstalled = () => {
      globalDeferredPrompt = null;
      setIsInstalled(true);
      try {
        localStorage.setItem(INSTALLED_STORAGE_KEY, 'true');
      } catch {}
      notifyListeners();
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      listeners.delete(syncState);
      if (typeof mediaQuery.removeEventListener === 'function') {
        mediaQuery.removeEventListener('change', handleDisplayModeChange);
      }
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  const install = useCallback(async () => {
    if (!globalDeferredPrompt) return false;
    try {
      await globalDeferredPrompt.prompt();
      const { outcome } = await globalDeferredPrompt.userChoice;
      if (outcome === 'accepted') {
        globalDeferredPrompt = null;
        setIsInstalled(true);
        try {
          localStorage.setItem(INSTALLED_STORAGE_KEY, 'true');
        } catch {}
        notifyListeners();
        return true;
      }
    } catch {
      // Prompt was already used or dismissed
      globalDeferredPrompt = null;
      notifyListeners();
    }
    return false;
  }, []);

  return {
    // Strictly false whenever already installed
    isInstallable: !isInstalled && !!deferredPrompt,
    isInstalled,
    isIOS: !isInstalled && isIOS,
    install,
  };
}

/**
 * Online / Offline connectivity hook
 */
export function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState<boolean>(
    typeof navigator !== 'undefined' ? navigator.onLine : true
  );

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return isOnline;
}

/**
 * Bulletproof Service Worker Update & Cache Refresh Hook
 * Prevents stale app versions and avoids infinite controllerchange reload loops.
 */
const UPDATE_INTERVAL_MS = 6 * 60 * 60 * 1000; // 6 hours
const SW_LAST_CHECK_KEY = 'quader_sw_last_update_check';
const SW_PENDING_RETRY_KEY = 'quader_sw_pending_network_retry';

// Shared singleton service worker registration reference
let globalSwRegistration: ServiceWorkerRegistration | null = null;
const swSubscribers = new Set<() => void>();

function notifySwSubscribers() {
  swSubscribers.forEach(cb => cb());
}

// Initial page load timestamp used to detect if the server has newer assets or builds
// Initial page load timestamp used to detect if the server has newer assets or builds
let INITIAL_LOAD_TIME = Date.now();

export function setInitialLoadTimeForTesting(time: number) {
  INITIAL_LOAD_TIME = time;
}

/**
 * Directly inspects the server for website updates (such as homepage edits or asset changes),
 * even if the service worker script (sw.js) did not change a single byte.
 */
export async function checkServerForWebsiteUpdates(): Promise<boolean> {
  if (typeof window === 'undefined' || typeof document === 'undefined') return false;

  const timestamp = Date.now();

  // 1. Check /version.json with no-store cache against acknowledged build time
  try {
    const vRes = await fetch(`/version.json?_t=${timestamp}`, {
      cache: 'no-store',
      headers: {
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        Pragma: 'no-cache',
      },
    });
    if (vRes.ok) {
      const data = await vRes.json();
      if (data && typeof data.buildTime === 'number' && data.buildTime > 0) {
        const acknowledgedBuildTime = Number(localStorage.getItem('quader_acknowledged_build_time') || '0');
        if (data.buildTime > acknowledgedBuildTime && data.buildTime > INITIAL_LOAD_TIME) {
          return true;
        }
      }
    }
  } catch {}

  // 2. Fetch /index.html with no-store cache to inspect script / stylesheet changes
  try {
    const htmlRes = await fetch(`/index.html?_t=${timestamp}`, {
      cache: 'no-store',
      headers: {
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        Pragma: 'no-cache',
      },
    });
    if (htmlRes.ok) {
      const htmlText = await htmlRes.text();

      // Current document active scripts normalized to pathname
      const currentScripts = new Set<string>();
      document.querySelectorAll<HTMLScriptElement>('script[src]').forEach(s => {
        const raw = s.getAttribute('src');
        if (raw) {
          try {
            currentScripts.add(new URL(raw, window.location.origin).pathname);
          } catch {
            currentScripts.add(raw);
          }
        }
      });

      // Server index.html scripts
      const scriptMatches = htmlText.matchAll(/<script[^>]+src=["']([^"']+)["']/gi);
      for (const m of scriptMatches) {
        let src = m[1];
        if (src) {
          try {
            src = new URL(src, window.location.origin).pathname;
          } catch {}
          // Only compare primary app bundle scripts under /assets/
          if (src.includes('/assets/') && currentScripts.size > 0 && !currentScripts.has(src)) {
            return true;
          }
        }
      }

      // Current document active styles normalized to pathname
      const currentStyles = new Set<string>();
      document.querySelectorAll<HTMLLinkElement>('link[rel="stylesheet"][href]').forEach(l => {
        const raw = l.getAttribute('href');
        if (raw) {
          try {
            currentStyles.add(new URL(raw, window.location.origin).pathname);
          } catch {
            currentStyles.add(raw);
          }
        }
      });

      // Server index.html stylesheets
      const styleMatches = htmlText.matchAll(/<link[^>]+rel=["']stylesheet["'][^>]+href=["']([^"']+)["']/gi);
      for (const m of styleMatches) {
        let href = m[1];
        if (href) {
          try {
            href = new URL(href, window.location.origin).pathname;
          } catch {}
          if (href.includes('/assets/') && currentStyles.size > 0 && !currentStyles.has(href)) {
            return true;
          }
        }
      }
    }
  } catch {}

  return false;
}

/**
 * Robust Service Worker Update & Cache Refresh Hook
 * - Checks every 6 hours for website updates
 * - If a check fails due to offline/no-network, queues a retry that fires immediately when network reconnects
 * - Prompts user to click to update (does not auto-reload mid-work)
 */
export function useServiceWorkerUpdater() {
  const refreshingRef = useRef(false);
  const [lastCheckTime, setLastCheckTime] = useState<number>(() => {
    try {
      return Number(localStorage.getItem(SW_LAST_CHECK_KEY) || Date.now());
    } catch {
      return Date.now();
    }
  });
  const [isChecking, setIsChecking] = useState<boolean>(false);
  const [hasPendingRetry, setHasPendingRetry] = useState<boolean>(() => {
    try {
      return localStorage.getItem(SW_PENDING_RETRY_KEY) === 'true';
    } catch {
      return false;
    }
  });

  const {
    needRefresh: [needRefresh, setNeedRefresh],
    updateServiceWorker,
  } = useRegisterSW({
    onRegisteredSW(_swUrl, registration) {
      if (!registration) return;

      // Immediately unregister dev-sw.js if detected
      if (registration.active?.scriptURL.includes('dev-sw.js') || registration.installing?.scriptURL.includes('dev-sw.js')) {
        registration.unregister().catch(() => {});
        return;
      }

      globalSwRegistration = registration;
      notifySwSubscribers();

      // Core update executor that safely checks the server for updated Service Worker
      const executeUpdateCheck = async (source: string) => {
        if (!registration) return;

        // If user dismissed update in this session, do not re-prompt
        try {
          if (sessionStorage.getItem('quader_update_dismissed') === 'true') {
            return;
          }
        } catch {}

        // If currently offline, defer check until network returns
        if (typeof navigator !== 'undefined' && !navigator.onLine) {
          try {
            localStorage.setItem(SW_PENDING_RETRY_KEY, 'true');
            setHasPendingRetry(true);
          } catch {}
          return;
        }

        try {
          await registration.update();
          const swHasUpdate = !!(registration.waiting || (registration.active && registration.installing));
          // Only check server HTML/version on periodic or network restore, never on fresh initial startup
          const serverHasUpdate = source !== 'initial-startup' ? await checkServerForWebsiteUpdates() : false;

          if (swHasUpdate || serverHasUpdate) {
            setNeedRefresh(true);
            if (registration.waiting) {
              try {
                registration.waiting.postMessage({ type: 'SKIP_WAITING' });
              } catch {}
            }
          }

          const now = Date.now();
          try {
            localStorage.setItem(SW_LAST_CHECK_KEY, String(now));
            localStorage.removeItem(SW_PENDING_RETRY_KEY);
            setLastCheckTime(now);
            setHasPendingRetry(false);
          } catch {}
        } catch (err) {
          // Network failed during update check — queue automatic retry on next online event
          console.warn(`[PWA Update] Check failed (${source}), scheduling network retry:`, err);
          try {
            localStorage.setItem(SW_PENDING_RETRY_KEY, 'true');
            setHasPendingRetry(true);
          } catch {}
        }
      };

      // 1. Immediate startup check on every registration to detect new deployments
      executeUpdateCheck('initial-startup');

      // 2. Periodic background check every 6 hours
      const intervalId = setInterval(() => {
        executeUpdateCheck('6-hour-periodic');
      }, UPDATE_INTERVAL_MS);

      // 3. Network reconnection handler: if an update check was delayed due to no network, run immediately
      const handleOnline = () => {
        const last = Number(localStorage.getItem(SW_LAST_CHECK_KEY) || '0');
        const pendingRetry = localStorage.getItem(SW_PENDING_RETRY_KEY) === 'true';
        if (pendingRetry || Date.now() - last >= UPDATE_INTERVAL_MS) {
          executeUpdateCheck('network-restored');
        }
      };
      window.addEventListener('online', handleOnline);

      // 4. Foregrounding check: check if tab returns to view after >= 6 hours
      const handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
          const last = Number(localStorage.getItem(SW_LAST_CHECK_KEY) || '0');
          const pendingRetry = localStorage.getItem(SW_PENDING_RETRY_KEY) === 'true';
          if (pendingRetry || Date.now() - last >= UPDATE_INTERVAL_MS) {
            executeUpdateCheck('tab-foreground');
          }
        }
      };
      document.addEventListener('visibilitychange', handleVisibilityChange);

      // 5. Periodic Background Sync registration for Chromium PWAs
      if ('periodicSync' in registration) {
        try {
          // @ts-ignore
          registration.periodicSync.register('quader-catalog-update', {
            minInterval: UPDATE_INTERVAL_MS,
          }).catch(() => {});
        } catch {}
      }

      return () => {
        clearInterval(intervalId);
        window.removeEventListener('online', handleOnline);
        document.removeEventListener('visibilitychange', handleVisibilityChange);
      };
    },
    onRegisterError(error) {
      console.warn('Service Worker registration notice:', error);
    },
  });

  useEffect(() => {
    if (typeof window !== 'undefined' && 'caches' in window) {
      // Purge any legacy pre-v3 caches that may hold outdated route chunks
      caches
        .keys()
        .then(keys => {
          keys.forEach(key => {
            if (
              key.startsWith('quader-') &&
              !key.includes('-v7') &&
              !key.startsWith('quader-store-v7')
            ) {
              caches.delete(key).catch(() => {});
            }
          });
        })
        .catch(() => {});
    }

    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;

    const handleControllerChange = () => {
      if (refreshingRef.current) return;
      refreshingRef.current = true;
      window.location.reload();
    };

    navigator.serviceWorker.addEventListener('controllerchange', handleControllerChange);
    return () => {
      navigator.serviceWorker.removeEventListener('controllerchange', handleControllerChange);
    };
  }, []);

  const applyUpdate = useCallback(async () => {
    try {
      // 0. Record current server build time as acknowledged so we don't loop prompt after reloading
      try {
        const vRes = await fetch(`/version.json?_t=${Date.now()}`, { cache: 'no-store' });
        if (vRes.ok) {
          const data = await vRes.json();
          if (data && typeof data.buildTime === 'number') {
            localStorage.setItem('quader_acknowledged_build_time', String(data.buildTime));
          } else {
            localStorage.setItem('quader_acknowledged_build_time', String(Date.now()));
          }
        } else {
          localStorage.setItem('quader_acknowledged_build_time', String(Date.now()));
        }
      } catch {
        localStorage.setItem('quader_acknowledged_build_time', String(Date.now()));
      }

      setNeedRefresh(false);

      // 1. Post skipWaiting to any waiting service worker
      let reg = globalSwRegistration;
      if (!reg && typeof navigator !== 'undefined' && 'serviceWorker' in navigator) {
        reg = await navigator.serviceWorker.getRegistration();
      }
      if (reg?.waiting) {
        try {
          reg.waiting.postMessage({ type: 'SKIP_WAITING' });
        } catch {}
      }

      // 2. Clear old browser CacheStorage caches to wipe out old cached HTML/JS/CSS
      if (typeof window !== 'undefined' && 'caches' in window) {
        try {
          const cacheKeys = await caches.keys();
          await Promise.all(cacheKeys.map(k => caches.delete(k)));
        } catch (e) {
          console.warn('Cache purge error during update:', e);
        }
      }

      // 3. Delegate to VitePWA updateServiceWorker(true) for standard activation
      if (updateServiceWorker) {
        await updateServiceWorker(true);
      }

      // 4. Fallback reload if controllerchange does not reload within 400ms
      setTimeout(() => {
        if (!refreshingRef.current) {
          refreshingRef.current = true;
          const current = new URL(window.location.href);
          current.searchParams.delete('_ts');
          window.location.replace(current.toString());
        }
      }, 400);
    } catch {
      window.location.reload();
    }
  }, [setNeedRefresh, updateServiceWorker]);

  const checkForUpdateManual = useCallback(async (): Promise<{
    status: 'updated' | 'up-to-date' | 'offline' | 'error';
    message: string;
  }> => {
    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      try {
        localStorage.setItem(SW_PENDING_RETRY_KEY, 'true');
        setHasPendingRetry(true);
      } catch {}
      return {
        status: 'offline',
        message: 'You are currently offline. An update check will trigger automatically when your internet reconnects.',
      };
    }

    setIsChecking(true);
    try {
      let reg = globalSwRegistration;
      if (!reg && typeof navigator !== 'undefined' && 'serviceWorker' in navigator) {
        reg = await navigator.serviceWorker.getRegistration();
      }

      if (reg) {
        try {
          await reg.update();
        } catch (e) {
          console.warn('SW manual update check notice:', e);
        }
      }

      // Check whether SW found a waiting/installing worker OR server files changed (e.g. homepage or HTML)
      const swHasUpdate = !!(reg && (reg.waiting || reg.installing));
      const serverHasUpdate = await checkServerForWebsiteUpdates();

      if (swHasUpdate || serverHasUpdate) {
        setNeedRefresh(true);
        if (reg?.waiting) {
          try {
            reg.waiting.postMessage({ type: 'SKIP_WAITING' });
          } catch {}
        }
        return {
          status: 'updated',
          message: 'A new website release is ready! Click "Click to Update & Reload Website" below to apply.',
        };
      }

      const now = Date.now();
      try {
        localStorage.setItem(SW_LAST_CHECK_KEY, String(now));
        localStorage.removeItem(SW_PENDING_RETRY_KEY);
        setLastCheckTime(now);
        setHasPendingRetry(false);
      } catch {}

      return {
        status: 'up-to-date',
        message: 'The website is running the latest version. No new update was found on the server.',
      };
    } catch (err) {
      console.warn('Manual update check error:', err);
      try {
        localStorage.setItem(SW_PENDING_RETRY_KEY, 'true');
        setHasPendingRetry(true);
      } catch {}
      return {
        status: 'error',
        message: 'Network check could not be completed. Will retry automatically once internet stabilizes.',
      };
    } finally {
      setIsChecking(false);
    }
  }, [setNeedRefresh]);

  return {
    needRefresh,
    isChecking,
    lastCheckTime,
    hasPendingRetry,
    dismissUpdate: () => {
      setNeedRefresh(false);
      try {
        sessionStorage.setItem('quader_update_dismissed', 'true');
      } catch {}
    },
    applyUpdate,
    checkForUpdateManual,
  };
}

/**
 * Bug-Free Opt-In Release Notification Manager
 * Uses ServiceWorkerRegistration.showNotification with deterministic deduplication tags.
 */
export function useReleaseNotifications() {
  const isSupported =
    typeof window !== 'undefined' &&
    'Notification' in window &&
    'serviceWorker' in navigator;

  const [permission, setPermission] = useState<NotificationPermission>(() => {
    if (!isSupported) return 'default';
    return Notification.permission;
  });

  const [isOptedIn, setIsOptedIn] = useState<boolean>(() => {
    try {
      return localStorage.getItem(NOTIF_OPT_IN_KEY) === 'true' && isSupported && Notification.permission === 'granted';
    } catch {
      return false;
    }
  });

  const sendSafeNotification = useCallback(
    async (title: string, body: string, tag = 'quader-store-notification') => {
      if (!isSupported || Notification.permission !== 'granted') return false;
      try {
        const registration = await navigator.serviceWorker.getRegistration();
        const options: NotificationOptions = {
          body,
          icon: '/pwa-192x192.png',
          badge: '/pwa-192x192.png',
          tag, // Prevents duplicate stacked notifications
          silent: false,
        };
        if (registration && typeof registration.showNotification === 'function') {
          await registration.showNotification(title, options);
          return true;
        } else {
          new Notification(title, options);
          return true;
        }
      } catch {
        return false;
      }
    },
    [isSupported]
  );

  const toggleNotifications = useCallback(async (): Promise<{ enabled: boolean; message: string }> => {
    if (!isSupported) {
      return { enabled: false, message: 'Push notifications are not supported in this browser environment.' };
    }

    if (isOptedIn) {
      setIsOptedIn(false);
      try {
        localStorage.setItem(NOTIF_OPT_IN_KEY, 'false');
      } catch {}
      return { enabled: false, message: 'Release push notifications muted.' };
    }

    if (Notification.permission === 'denied') {
      setPermission('denied');
      return {
        enabled: false,
        message: 'Notifications are blocked in browser settings. Enable permissions for this site to receive alerts.',
      };
    }

    try {
      const result =
        Notification.permission === 'granted'
          ? 'granted'
          : await Notification.requestPermission();
      setPermission(result);

      if (result === 'granted') {
        setIsOptedIn(true);
        try {
          localStorage.setItem(NOTIF_OPT_IN_KEY, 'true');
        } catch {}
        await sendSafeNotification(
          'Quader Store Release Alerts Active',
          'You will be notified when new MQL5 engines or SaaS releases are published.',
          'quader-optin-confirmation'
        );
        return { enabled: true, message: 'Release push notifications enabled.' };
      }

      return { enabled: false, message: 'Notification permission was not granted.' };
    } catch {
      return { enabled: false, message: 'Could not enable notifications in this view.' };
    }
  }, [isSupported, isOptedIn, sendSafeNotification]);

  return {
    isSupported,
    permission,
    isOptedIn,
    toggleNotifications,
    sendSafeNotification,
  };
}
