
import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

// Suppress benign ResizeObserver errors commonly seen in development
const originalError = console.error;
console.error = (...args) => {
  const firstArg = args[0];
  const errorMessage = firstArg instanceof Error ? firstArg.message : String(firstArg);
  
  if (errorMessage.includes('ResizeObserver loop completed with undelivered notifications') || 
      errorMessage.includes('ResizeObserver loop limit exceeded')) {
    return;
  }
  originalError(...args);
};

window.addEventListener('error', (e) => {
  // Check message content safely
  const msg = e.message || '';
  if (msg.includes('ResizeObserver loop completed with undelivered notifications') ||
      msg.includes('ResizeObserver loop limit exceeded')) {
    e.stopImmediatePropagation();
  }
});

// Synchronously restore GitHub Pages redirect path before React Router initializes
if (typeof window !== 'undefined') {
  try {
    const redirect = sessionStorage.getItem('spa_redirect');
    if (redirect) {
      sessionStorage.removeItem('spa_redirect');
      window.history.replaceState(null, '', redirect);
    }
  } catch {}

  const search = window.location.search || '';
  if (search) {
    let raw = '';
    if (search.startsWith('?/')) {
      raw = search.slice(2);
    } else if (search.startsWith('?p=/')) {
      raw = search.slice(4);
    } else if (search.startsWith('?/p=')) {
      raw = search.slice(4);
    } else if (search.startsWith('?p=')) {
      raw = search.slice(3);
    } else if (search.includes('?/')) {
      raw = search.slice(search.indexOf('?/') + 2);
    }
    if (raw) {
      const decoded = raw.split('&').map(s => s.replace(/~and~/g, '&')).join('?');
      const target = '/' + decoded.replace(/^\/+/, '');
      window.history.replaceState(null, '', target + window.location.hash);
    }
  }
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
