interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class StoreErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  override state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  override componentDidCatch(error: unknown, errorInfo: ErrorInfo) {
    console.warn('StoreErrorBoundary caught render error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-[70vh] flex flex-col items-center justify-center text-center px-4 py-24">
          <h2 className="font-display text-xl sm:text-2xl font-bold text-slate-900 dark:text-white mb-2">
            View Reload Required
          </h2>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 max-w-md mb-6">
            A cached view state was updated. Tap below to refresh the current view.
          </p>
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => this.setState({ hasError: false })}
              className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg text-xs font-semibold transition-colors"
            >
              Retry View
            </button>
            <button
              type="button"
              onClick={() => {
                this.setState({ hasError: false });
                window.location.assign('/');
              }}
              className="px-5 py-2.5 border border-[#E4E4DE] dark:border-[#222630] text-slate-700 dark:text-slate-300 rounded-lg text-xs font-semibold"
            >
              Back to Catalog
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const isDashboard = location.pathname.startsWith('/dashboard') || location.pathname.startsWith('/shop/dashboard') || location.pathname.startsWith('/admin');
  const isCoursePlayer = location.pathname.includes('/course/');

  // Handle GitHub Pages SPA redirects (?/... and sessionStorage) and legacy hash-routed links (#/...)
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // 1. Check sessionStorage for pending redirect from 404.html
    try {
      const redirect = sessionStorage.getItem('spa_redirect');
      if (redirect) {
        sessionStorage.removeItem('spa_redirect');
        window.history.replaceState(null, '', redirect + window.location.hash);
        navigate(redirect + window.location.hash, { replace: true });
        return;
      }
    } catch {}

    // 2. Check query string redirect: ?/path, ?p=/path, ?/p=/path (e.g. https://store.quader864.ir/?/auth/login)
    const search = window.location.search || location.search || '';
    if (search) {
      let raw = '';
      if (search.startsWith('?/')) {
        raw = search.slice(2);
      } else if (search.startsWith('?p=/')) {
        raw = search.slice(4);
      } else if (search.startsWith('?/p=')) {
        raw = search.slice(4);
      } else if (search.startsWith('?p=')) {
        raw = search.slice(3);
      } else if (search.includes('?/')) {
        raw = search.slice(search.indexOf('?/') + 2);
      }
      if (raw) {
        const decoded = raw.split('&').map(s => s.replace(/~and~/g, '&')).join('?');
        const targetPath = '/' + decoded.replace(/^\/+/, '');
        
        // Clean up the address bar immediately from /?/auth/login to /auth/login
        window.history.replaceState(null, '', targetPath + window.location.hash);
        navigate(targetPath + window.location.hash, { replace: true });
        return;
      }
    }

    // 3. Support any legacy hash-routed links (#/...)
    if (window.location.hash && window.location.hash.startsWith('#/')) {
      const targetPath = window.location.hash.slice(1);
      window.history.replaceState(null, '', targetPath);
      navigate(targetPath, { replace: true });
    }
  }, [navigate, location.search]);

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] text-slate-900 dark:text-slate-100 font-sans selection:bg-emerald-500/25 selection:text-slate-900 dark:selection:text-white transition-colors duration-200 flex flex-col">
      <a
        href="#main-content"
        className="sr-only focus:not-sr-only focus:fixed focus:top-3 focus:left-3 focus:z-100 focus:px-4 focus:py-2 focus:rounded-lg focus:bg-emerald-600 focus:text-white focus:text-xs focus:font-semibold"
      >
        Skip to main content
      </a>
      <SEOHead />
      <ScrollToTop />
      {!isCoursePlayer && <Header />}
      <main id="main-content" className="flex-1">
        <React.Fragment key={location.pathname}>
          <StoreErrorBoundary>
            {children}
          </StoreErrorBoundary>
        </React.Fragment>
      </main>
      {!isCoursePlayer && <ComparisonMatrix />}
      <PWAManager />
      <FloatingNotificationWidget />
      {!isCoursePlayer && !isDashboard && <Footer />}
    </div>
  );
};

