import React from 'react';
import { Navigate, useLocation, Link } from 'react-router-dom';
import { useAuth, hasRolePermission } from '../context/AuthContext';
import { UserRole } from '../types';
import { ShieldAlert, LogIn, ArrowLeft } from 'lucide-react';
import PageLoader from './PageLoader';

interface RequireAuthProps {
  children: React.ReactNode;
}

export const RequireAuth: React.FC<RequireAuthProps> = ({ children }) => {
  const { user, isLoading } = useAuth();
  const location = useLocation();

  if (isLoading) {
    return <PageLoader />;
  }

  if (!user) {
    return <Navigate to="/auth/login" state={{ from: location }} replace />;
  }

  return <>{children}</>;
};

interface RequireRoleProps {
  allowedRoles: UserRole[];
  children: React.ReactNode;
}

export const RequireRole: React.FC<RequireRoleProps> = ({ allowedRoles, children }) => {
  const { user, isLoading } = useAuth();
  const location = useLocation();

  if (isLoading) {
    return <PageLoader />;
  }

  if (!user) {
    return <Navigate to="/auth/login" state={{ from: location }} replace />;
  }

  const isPermitted = hasRolePermission(user.role, allowedRoles);

  if (!isPermitted) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center text-center px-4 py-20 max-w-xl mx-auto">
        <div className="w-14 h-14 rounded-2xl bg-amber-500/10 border border-amber-500/20 text-amber-500 flex items-center justify-center mb-6">
          <ShieldAlert size={28} />
        </div>
        <h1 className="font-display text-2xl font-bold text-slate-900 dark:text-white mb-2">
          Access Restricted
        </h1>
        <p className="text-sm text-slate-600 dark:text-slate-400 mb-6 leading-relaxed">
          Your current account role (<span className="font-mono font-semibold text-emerald-600 dark:text-emerald-400">{user.role || 'user'}</span>) does not have authorization to view this operations workspace.
        </p>
        <div className="p-4 rounded-xl bg-slate-100 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 text-xs text-left text-slate-600 dark:text-slate-400 mb-8 w-full">
          <div className="font-semibold text-slate-800 dark:text-slate-200 mb-1">Permitted Roles:</div>
          <div className="font-mono flex flex-wrap gap-1.5 mt-2">
            {allowedRoles.map(role => (
              <span key={role} className="px-2 py-0.5 rounded bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                {role}
              </span>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Link
            to="/shop"
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-lg border border-slate-300 dark:border-slate-700 text-xs font-semibold hover:bg-slate-100 dark:hover:bg-slate-900 transition-colors"
          >
            <ArrowLeft size={14} />
            <span>Return to Store</span>
          </Link>
          <Link
            to="/auth/login"
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold transition-colors"
          >
            <LogIn size={14} />
            <span>Switch Account</span>
          </Link>
        </div>
      </div>
    );
  }

  return <>{children}</>;
};
