import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { shopApi, normalizeShopItem, CheckoutItemPayload, CheckoutSuccessResponse } from '../api/shop';
import { meApi } from '../api/me';
import { ShopConfig, DEFAULT_SHOP_CONFIG, formatShopCurrency, convertShopCurrencyAmount } from '../api/config';
import { ShopOrder, ShopProduct, ShopReview, ShopEntitlement } from '../types';
import { useAuth } from './AuthContext';

export interface CartItem extends ShopProduct {
  quantity: number;
  selectedVariantId?: string;
  selectedVariantName?: string;
}

export type CurrencyCode = 'IRR' | 'IRT' | string;

interface ShopContextType {
  shopConfig: ShopConfig;
  storeInventory: ShopProduct[];
  courses: ShopProduct[];
  bundles: ShopProduct[];
  subscriptions: any[];
  allCatalogItems: ShopProduct[];
  cart: CartItem[];
  orders: ShopOrder[];
  entitlements: ShopEntitlement[];
  reviews: Record<string, ShopReview[]>;
  isCartOpen: boolean;
  isLoading: boolean;
  error: string | null;

  // Currency & Pricing
  currency: CurrencyCode;
  setCurrency: (c: CurrencyCode) => void;
  formatPrice: (amount: number, overrideCurrency?: string) => string;

  // Promo Codes & Totals
  promoCode: string | null;
  discountPct: number;
  promoNotice: string | null;
  applyPromoCode: (code: string) => Promise<{ success: boolean; message: string }>;
  removePromoCode: () => void;
  cartTotal: number;
  discountAmount: number;
  finalTotal: number;
  cartCount: number;

  // Saved / Wishlist & Compare
  savedIds: string[];
  toggleSaved: (id: string) => void;
  isSaved: (id: string) => boolean;
  compareIds: string[];
  toggleCompare: (id: string) => void;
  clearCompare: () => void;
  isCompareOpen: boolean;
  setCompareOpen: (open: boolean) => void;

  // Toast Notification
  toastMessage: string | null;
  showToast: (msg: string) => void;

  // Actions
  refreshAll: () => Promise<void>;
  addToCart: (product: ShopProduct & { selectedVariantId?: string; selectedVariantName?: string }, openDrawer?: boolean) => Promise<void>;
  updateQuantity: (id: string, delta: number, variantId?: string) => Promise<void>;
  removeFromCart: (id: string, variantId?: string) => Promise<void>;
  clearCart: () => Promise<void>;
  toggleCart: (isOpen?: boolean) => void;
  checkout: (idempotencyKey?: string) => Promise<CheckoutSuccessResponse>;

  // Management
  addItem: (type: 'product' | 'course' | 'bundle' | 'subscription', data: any) => Promise<void>;
  updateItem: (type: 'product' | 'course' | 'bundle' | 'subscription', id: string, data: any) => Promise<void>;
  deleteItem: (type: 'product' | 'course' | 'bundle' | 'subscription', id: string) => Promise<void>;

  getStoreItem: (id: string) => ShopProduct | undefined;
  fetchReviewsForProduct: (productId: string, itemType?: string) => Promise<ShopReview[]>;
  addReview: (productId: string, review: ShopReview) => void;
  submitReviewToApi: (
    productId: string,
    rating: number,
    content: string,
    itemType?: string
  ) => Promise<{ success: boolean; message: string }>;
  completeVerifiedPayment: (conf: {
    paymentId: string;
    orderId?: string;
    amount: number;
    refId?: string;
    verifiedAt?: string;
  }) => void;
  checkVerifiedBuyer: (productId: string) => boolean;
  isEntitled: (idOrSlug: string) => boolean;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [shopConfig, setShopConfig] = useState<ShopConfig>(DEFAULT_SHOP_CONFIG);
  const [storeInventory, setStoreInventory] = useState<ShopProduct[]>([]);
  const [courses, setCourses] = useState<ShopProduct[]>([]);
  const [bundles, setBundles] = useState<ShopProduct[]>([]);
  const [subscriptions, setSubscriptions] = useState<any[]>([]);
  const [entitlements, setEntitlements] = useState<ShopEntitlement[]>([]);

  // Authoritative global currency initialized from GET /api/shop/config
  const [currency, setCurrencyState] = useState<CurrencyCode>(DEFAULT_SHOP_CONFIG.currency);

  const [promoCode, setPromoCode] = useState<string | null>(null);
  const [discountPct, setDiscountPct] = useState<number>(0);
  const [fixedPromoAmount, setFixedPromoAmount] = useState<number>(0);
  const [promoNotice, setPromoNotice] = useState<string | null>(null);

  const [savedIds, setSavedIds] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('quader_store_saved');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [compareIds, setCompareIds] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('quader_store_compare');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });
  const [isCompareOpen, setCompareOpen] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Cart state: local draft for guests; server-synced for authenticated users
  const [cart, setCart] = useState<CartItem[]>(() => {
    try {
      const saved = localStorage.getItem('quader_store_guest_cart') || localStorage.getItem('quader_store_cart');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  // Orders are no-store; never cached in localStorage
  const [orders, setOrders] = useState<ShopOrder[]>([]);

  const [reviews, setReviews] = useState<Record<string, ShopReview[]>>({});
  const reviewsRef = useRef<Record<string, ShopReview[]>>({});
  reviewsRef.current = reviews;

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const showToast = useCallback((msg: string) => {
    setToastMessage(msg);
    setTimeout(() => {
      setToastMessage(prev => (prev === msg ? null : prev));
    }, 3200);
  }, []);

  const setCurrency = (c: CurrencyCode) => {
    setCurrencyState(c);
  };

  const formatPrice = useCallback(
    (amount: number, overrideCurrency?: string) => {
      const baseCurrency = shopConfig.currency || 'IRR';
      if (overrideCurrency) {
        return formatShopCurrency(amount, overrideCurrency);
      }
      const displayCurrency = currency || baseCurrency;
      const convertedAmount = convertShopCurrencyAmount(amount, baseCurrency, displayCurrency);
      return formatShopCurrency(convertedAmount, displayCurrency);
    },
    [currency, shopConfig.currency]
  );

  // Sync guest cart to local storage only if unauthenticated
  useEffect(() => {
    if (!user) {
      try {
        localStorage.setItem('quader_store_guest_cart', JSON.stringify(cart));
      } catch {}
    }
  }, [cart, user]);

  useEffect(() => {
    try {
      localStorage.setItem('quader_store_saved', JSON.stringify(savedIds));
    } catch {}
  }, [savedIds]);

  useEffect(() => {
    try {
      localStorage.setItem('quader_store_compare', JSON.stringify(compareIds));
    } catch {}
  }, [compareIds]);

  const allCatalogItems = [...storeInventory, ...courses, ...bundles];

  const fetchAllData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const config = await shopApi.getConfig();
      setShopConfig(config);
      if (config.currency) {
        setCurrencyState(config.currency);
      }

      const [prodRes, courseRes, bundleRes, subRes] = await Promise.all([
        shopApi.getProducts({ limit: 100 }),
        shopApi.getCourses({ limit: 100 }),
        shopApi.getBundles({ limit: 100 }),
        shopApi.getSubscriptions({ limit: 100 }),
      ]);

      setStoreInventory(prodRes.products || []);
      setCourses(courseRes.courses || []);
      setBundles(bundleRes.bundles || []);
      setSubscriptions(subRes.subscriptions || []);

      // If user is authenticated, load entitlements and server cart
      if (user) {
        try {
          const libRes = await shopApi.getLibrary();
          if (libRes.entitlements) {
            setEntitlements(libRes.entitlements);
          }
        } catch {}

        try {
          const cartRes = await meApi.getCart();
          if (cartRes.items && cartRes.items.length > 0) {
            // Rehydrate cart items against catalog (including subscriptions)
            const allItems = [
              ...(prodRes.products || []),
              ...(courseRes.courses || []),
              ...(bundleRes.bundles || []),
              ...(subRes.subscriptions || []),
            ];
            const rehydrated: CartItem[] = cartRes.items.map((ci: any) => {
              const targetId = String(ci.itemId || ci.id || '');
              const matched = allItems.find(item => item.id === targetId || item.slug === targetId);
              const variant = matched?.variants?.find(
                (v: any) => (v.id || v._id) === ci.variantId
              );
              if (matched) {
                return {
                  ...matched,
                  price: variant?.price ?? matched.price,
                  selectedVariantId: ci.variantId || undefined,
                  selectedVariantName: variant?.name,
                  quantity: ci.quantity,
                };
              }
              return {
                id: targetId,
                title: ci.name || 'Catalog Item',
                price: Number(ci.unitAmount || ci.price || 0),
                currency: (config.currency || 'IRR') as any,
                type: ci.itemType || ci.type || 'product',
                image: ci.image || '',
                rating: 5,
                reviewsCount: 0,
                tags: [],
                description: '',
                features: [],
                selectedVariantId: ci.variantId || undefined,
                quantity: ci.quantity,
              };
            });
            setCart(rehydrated);
          }
        } catch {}
      } else {
        setEntitlements([]);
      }
    } catch (e: any) {
      console.warn('Catalog initialization note:', e);
      setError(e?.message || 'Failed to load catalog');
    } finally {
      setIsLoading(false);
    }
  }, [user]);

  useEffect(() => {
    fetchAllData();
  }, [fetchAllData]);

  // Authenticated server cart syncing
  const addToCart = async (product: ShopProduct & { selectedVariantId?: string; selectedVariantName?: string }, openDrawer = true) => {
    const chosenVariantId = product.selectedVariantId || product.variants?.[0]?.id || (product.variants?.[0] as any)?._id;
    const chosenVariantName =
      product.selectedVariantName ||
      product.variants?.find(v => (v.id || (v as any)._id) === chosenVariantId)?.name;
    const isSingleQuantity = product.type === 'course' || product.type === 'subscription';
    const existing = cart.find(p => p.id === product.id && (p.selectedVariantId || p.variants?.[0]?.id) === chosenVariantId);

    if (existing && isSingleQuantity) {
      showToast(`"${product.title}" is already in your bag`);
      if (openDrawer) setIsCartOpen(true);
      return;
    }

    const nextQuantity = existing ? existing.quantity + 1 : 1;

    setCart(prev => {
      if (existing) {
        return prev.map(p =>
          p.id === product.id && (p.selectedVariantId || p.variants?.[0]?.id) === chosenVariantId
            ? { ...p, quantity: nextQuantity }
            : p
        );
      }
      return [
        ...prev,
        {
          ...product,
          selectedVariantId: chosenVariantId,
          ...(chosenVariantName ? { selectedVariantName: chosenVariantName } : {}),
          quantity: 1,
        },
      ];
    });

    if (user) {
      try {
        await meApi.addItemToCart(
          product.type === 'digital' ? 'product' : product.type,
          product.id,
          chosenVariantId,
          1
        );
      } catch (err) {
        console.warn('[Cart] Server sync notice:', err);
      }
    }

    if (openDrawer) {
      setIsCartOpen(true);
    }
    showToast(`Added "${product.title}" to bag`);
  };

  const updateQuantity = async (id: string, delta: number, variantId?: string) => {
    const matchesTarget = (p: CartItem) => {
      if (p.id !== id) return false;
      if (variantId === undefined) return true;
      return (p.selectedVariantId || p.variants?.[0]?.id || (p.variants?.[0] as any)?._id) === variantId;
    };

    const item = cart.find(matchesTarget);
    if (!item) return;

    if (item.type === 'course' || item.type === 'subscription') {
      if (delta < 0) {
        await removeFromCart(id, variantId);
      }
      return;
    }

    const nextQty = item.quantity + delta;
    if (nextQty <= 0) {
      await removeFromCart(id, variantId);
      return;
    }

    setCart(prev => prev.map(p => (matchesTarget(p) ? { ...p, quantity: nextQty } : p)));

    if (user) {
      try {
        await meApi.addItemToCart(
          item.type === 'digital' ? 'product' : item.type,
          item.id,
          item.selectedVariantId || item.variants?.[0]?.id,
          nextQty
        );
      } catch (err) {
        console.warn('[Cart] Server quantity update notice:', err);
      }
    }
  };

  const removeFromCart = async (id: string, variantId?: string) => {
    const matchesTarget = (p: CartItem) => {
      if (p.id !== id) return false;
      if (variantId === undefined) return true;
      return (p.selectedVariantId || p.variants?.[0]?.id || (p.variants?.[0] as any)?._id) === variantId;
    };

    const item = cart.find(matchesTarget);
    setCart(prev => prev.filter(p => !matchesTarget(p)));

    if (user && item) {
      try {
        await meApi.removeItemFromCart(
          item.type === 'digital' ? 'product' : item.type,
          item.id,
          item.selectedVariantId || item.variants?.[0]?.id
        );
      } catch (err) {
        console.warn('[Cart] Server remove notice:', err);
      }
    }
  };

  const clearCart = async () => {
    setCart([]);
    setPromoCode(null);
    setDiscountPct(0);
    setFixedPromoAmount(0);
    setPromoNotice(null);

    if (user) {
      try {
        await meApi.clearCart();
      } catch (err) {
        console.warn('[Cart] Server clear notice:', err);
      }
    }
  };

  const toggleCart = (isOpen?: boolean) => {
    setIsCartOpen(prev => (isOpen !== undefined ? isOpen : !prev));
  };

  const toggleSaved = (id: string) => {
    setSavedIds(prev => {
      const exists = prev.includes(id);
      const next = exists ? prev.filter(x => x !== id) : [...prev, id];
      showToast(exists ? 'Removed from Saved Systems' : 'Saved to your shortlist');
      return next;
    });
  };

  const isSaved = useCallback((id: string) => savedIds.includes(id), [savedIds]);

  const toggleCompare = (id: string) => {
    setCompareIds(prev => {
      if (prev.includes(id)) {
        return prev.filter(x => x !== id);
      }
      if (prev.length >= 3) {
        showToast('Comparison matrix supports up to 3 systems at once');
        return prev;
      }
      showToast('Added system to Comparison Matrix');
      return [...prev, id];
    });
  };

  const clearCompare = () => setCompareIds([]);

  /**
   * Authoritative Promotion Validation via POST /api/shop/promotions/validate
   * Note: The promotion evaluation is advisory; server re-evaluates at checkout.
   */
  const applyPromoCode = async (rawCode: string): Promise<{ success: boolean; message: string }> => {
    const code = rawCode.trim();
    if (!code) {
      return { success: false, message: 'Please enter a promotion code.' };
    }

    try {
      const itemsPayload = cart.map(i => ({
        type: i.type === 'digital' ? 'product' : i.type,
        id: i.id.replace(/-extended$/, ''),
        variantId: i.selectedVariantId || i.variants?.[0]?.id || null,
        quantity: i.quantity,
      }));

      const res = await shopApi.validatePromotion(code, itemsPayload);

      if (res.valid) {
        setPromoCode(code);
        const evalData = res.evaluation || (res as any);
        const fixedAmt = Number(evalData.fixedAmount ?? evalData.discountAmount ?? evalData.totalDiscount ?? 0);
        const pct = Number(evalData.percent ?? evalData.discountPercent ?? (fixedAmt > 0 ? 0 : 15));
        setDiscountPct(pct);
        setFixedPromoAmount(fixedAmt > 0 ? fixedAmt : 0);
        setPromoNotice(res.reason || 'Code valid. (Estimated discount — server re-evaluates at checkout).');
        showToast(`Promo code "${code}" applied`);
        return {
          success: true,
          message: `Code "${code}" applied (advisory estimate; checkout re-evaluates).`,
        };
      } else {
        setPromoCode(null);
        setDiscountPct(0);
        setFixedPromoAmount(0);
        setPromoNotice(null);
        return {
          success: false,
          message: res.reason || 'Invalid or expired promotion code.',
        };
      }
    } catch (err: any) {
      return {
        success: false,
        message: err?.error || err?.message || 'Could not validate promotion code.',
      };
    }
  };

  const removePromoCode = () => {
    setPromoCode(null);
    setDiscountPct(0);
    setFixedPromoAmount(0);
    setPromoNotice(null);
    showToast('Promo code removed');
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const discountAmount = fixedPromoAmount > 0
    ? Math.min(cartTotal, Math.round(fixedPromoAmount))
    : Math.round((cartTotal * discountPct) / 100);
  const finalTotal = Math.max(0, cartTotal - discountAmount);
  const cartCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  /**
   * Idempotent /api/shop/checkout caller
   * Generates and locks an 8-128 character Idempotency-Key adhering to backend pattern [A-Za-z0-9._:-].
   */
  const checkout = async (customIdempotencyKey?: string): Promise<CheckoutSuccessResponse> => {
    if (cart.length === 0) {
      throw new Error('Your cart is empty.');
    }

    if (cart.length > 50) {
      throw new Error('Checkout supports a maximum of 50 items.');
    }

    const key =
      customIdempotencyKey ||
      `chk-${Date.now()}-${Math.random().toString(36).substring(2, 10)}`;

    const checkoutItems: CheckoutItemPayload[] = cart.map(item => ({
      type: item.type === 'course' ? 'course' : (item.type === 'bundle' ? 'bundle' : (item.type === 'subscription' ? 'subscription' : 'product')),
      id: item.id.replace(/-extended$/, ''),
      variantId: item.selectedVariantId || item.variants?.[0]?.id || null,
      quantity: (item.type === 'course' || item.type === 'subscription') ? 1 : item.quantity,
    }));

    const res = await shopApi.checkout(checkoutItems, key, promoCode || undefined);
    return res;
  };

  const addItem = async (type: string, data: any) => {
    if (type === 'product') await shopApi.createProduct(data);
    if (type === 'course') await shopApi.createCourse(data);
    if (type === 'bundle') await shopApi.createBundle(data);
    if (type === 'subscription') await shopApi.createSubscription(data);
    await fetchAllData();
  };

  const updateItem = async (type: string, id: string, data: any) => {
    if (type === 'product') await shopApi.updateProduct(id, data);
    if (type === 'course') await shopApi.updateCourse(id, data);
    if (type === 'bundle') await shopApi.updateBundle(id, data);
    if (type === 'subscription') await shopApi.updateSubscription(id, data);
    await fetchAllData();
  };

  const deleteItem = async (type: string, id: string) => {
    if (type === 'product') await shopApi.deleteProduct(id);
    if (type === 'course') await shopApi.deleteCourse(id);
    if (type === 'bundle') await shopApi.deleteBundle(id);
    if (type === 'subscription') await shopApi.deleteSubscription(id);
    await fetchAllData();
  };

  const getStoreItem = (id: string) => {
    return [...allCatalogItems, ...subscriptions].find(item => item.id === id || item.slug === id);
  };

  const fetchReviewsForProduct = useCallback(
    async (productId: string, itemType?: string): Promise<ShopReview[]> => {
      if (!productId) return [];
      try {
        const res = await shopApi.getReviews(productId, itemType);
        const list = res.reviews || [];
        setReviews(prev => {
          const currentList = prev[productId];
          if (
            currentList &&
            currentList.length === list.length &&
            currentList.every((r, idx) => r.id === list[idx]?.id)
          ) {
            return prev;
          }
          return { ...prev, [productId]: list };
        });
        return list;
      } catch (err: any) {
        const isNetwork =
          err?.code === 'NETWORK_ERROR' ||
          err?.status === 0 ||
          (typeof navigator !== 'undefined' && !navigator.onLine) ||
          err?.message?.includes('Network') ||
          err?.message?.includes('Failed to fetch');
        if (isNetwork) {
          throw err;
        }
        return reviewsRef.current[productId] || [];
      }
    },
    []
  );

  const addReview = (productId: string, review: ShopReview) => {
    setReviews(prev => ({
      ...prev,
      [productId]: [review, ...(prev[productId] || [])],
    }));
  };

  const submitReviewToApi = async (
    productId: string,
    rating: number,
    content: string,
    itemType?: string
  ): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await shopApi.submitReview({
        productId,
        itemType,
        rating,
        content,
      });
      const updatedReviews = await shopApi.getReviews(productId, itemType);
      if (updatedReviews.reviews.length > 0) {
        setReviews(prev => ({ ...prev, [productId]: updatedReviews.reviews }));
      }
      return { success: true, message: res?.message || 'Review submitted successfully.' };
    } catch (err: any) {
      if (err.status === 403) {
        return { success: false, message: 'Only verified purchasers with active entitlements can submit a review.' };
      }
      if (err.status === 409) {
        return { success: false, message: 'You have already submitted a review for this release.' };
      }
      return { success: false, message: err.error || err.message || 'Could not submit review.' };
    }
  };

  const isEntitled = useCallback(
    (idOrSlug: string): boolean => {
      if (!idOrSlug) return false;
      const clean = idOrSlug.trim().toLowerCase().replace(/-extended$/, '');
      return entitlements.some(e => {
        const itemId = (e.itemId || '').toLowerCase();
        const slug = (e.slug || '').toLowerCase();
        const id = (e.id || (e as any)._id || '').toLowerCase();
        const itemKey = (e.itemKey || '').toLowerCase();
        return (
          itemId === clean ||
          slug === clean ||
          id === clean ||
          itemKey === clean ||
          itemId.replace(/-extended$/, '') === clean ||
          slug.replace(/-extended$/, '') === clean
        );
      });
    },
    [entitlements]
  );

  const checkVerifiedBuyer = useCallback(
    (productId: string): boolean => {
      return isEntitled(productId);
    },
    [isEntitled]
  );

  const completeVerifiedPayment = useCallback(
    (conf: {
      paymentId: string;
      orderId?: string;
      amount: number;
      refId?: string;
      verifiedAt?: string;
    }) => {
      setOrders(prev => [
        {
          id: conf.orderId || conf.paymentId,
          orderId: conf.orderId,
          paymentId: conf.paymentId,
          date: conf.verifiedAt || new Date().toISOString(),
          items: [...cart],
          total: conf.amount,
          status: 'PAID',
          fulfillmentStatus: 'COMPLETED',
        } as any,
        ...prev,
      ]);
      setCart([]);
      try {
        localStorage.removeItem('quader_store_guest_cart');
        localStorage.removeItem('quader_store_cart');
      } catch {}
    },
    [cart]
  );

  return (
    <ShopContext.Provider
      value={{
        shopConfig,
        storeInventory,
        courses,
        bundles,
        subscriptions,
        allCatalogItems,
        cart,
        orders,
        entitlements,
        reviews,
        isCartOpen,
        isLoading,
        error,
        currency,
        setCurrency,
        formatPrice,
        promoCode,
        discountPct,
        promoNotice,
        applyPromoCode,
        removePromoCode,
        cartTotal,
        discountAmount,
        finalTotal,
        cartCount,
        savedIds,
        toggleSaved,
        isSaved,
        compareIds,
        toggleCompare,
        clearCompare,
        isCompareOpen,
        setCompareOpen,
        toastMessage,
        showToast,
        refreshAll: fetchAllData,
        addToCart,
        updateQuantity,
        removeFromCart,
        clearCart,
        toggleCart,
        checkout,
        addItem,
        updateItem,
        deleteItem,
        getStoreItem,
        fetchReviewsForProduct,
        addReview,
        submitReviewToApi,
        completeVerifiedPayment,
        checkVerifiedBuyer,
        isEntitled,
      }}
    >
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) {
    throw new Error('useShop must be used within a ShopProvider');
  }
  return context;
};
