import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

let isPluginRegistered = false;

export function ensureGsapPlugins(): boolean {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return false;
  }

  // Skip animation orchestration inside jsdom unit test environments so assertions stay synchronous & deterministic
  if (typeof navigator !== 'undefined' && /jsdom/i.test(navigator.userAgent || '')) {
    return false;
  }

  if (!isPluginRegistered) {
    try {
      gsap.registerPlugin(ScrollTrigger);
      isPluginRegistered = true;
    } catch {
      return false;
    }
  }

  return true;
}

export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return true;
  }
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

export function canAnimate(): boolean {
  return ensureGsapPlugins() && !prefersReducedMotion();
}

/**
 * Parses metric strings such as "99.94%", "< 12ms", "1,420+", "99 / 100"
 * and animates the numeric segment smoothly using GSAP while preserving prefix/suffix formatting.
 */
export function animateMetricValue(
  el: HTMLElement,
  rawText: string,
  triggerEl: HTMLElement,
  delay = 0
): gsap.core.Tween | null {
  const match = rawText.match(/^([^\d-]*?)([\d,]+(?:\.\d+)?)(.*)$/);
  if (!match) return null;

  const [, prefix, numStr, suffix] = match;
  const target = parseFloat(numStr.replace(/,/g, ''));
  if (!Number.isFinite(target)) return null;

  const decimalMatch = numStr.match(/\.(\d+)/);
  const decimals = decimalMatch ? decimalMatch[1].length : 0;
  const useGrouping = numStr.includes(',');

  const state = { val: 0 };

  return gsap.to(state, {
    val: target,
    duration: 1.25,
    delay,
    ease: 'power3.out',
    scrollTrigger: {
      trigger: triggerEl,
      start: 'top 92%',
      once: true,
    },
    onUpdate: () => {
      const formatted = decimals > 0
        ? state.val.toFixed(decimals)
        : useGrouping
          ? Math.round(state.val).toLocaleString('en-US')
          : String(Math.round(state.val));
      el.textContent = `${prefix}${formatted}${suffix}`;
    },
    onComplete: () => {
      el.textContent = rawText;
    },
  });
}

export { gsap, ScrollTrigger };
